package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import nl.dexanddice.solsurvivor.core.BoardEntry;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The leaderboard's requests (core.BoardEntry), sent by the plugin's injected RuneLite HTTP client, and the site's
 * answers read with RuneLite's Gson: a wave put on the boards once the site has its log, and all of the player's times
 * taken off by Remove my times. An answer is read up to MAX_ANSWER bytes, as the site's are a line of JSON.
 */
final class BoardUpload
{
	/** The most of an answer read: the site's are under 300 bytes. */
	private static final int MAX_ANSWER = 4096;

	private BoardUpload()
	{
	}

	/** The request that puts a wave on the boards, with its body (BoardEntry.body). */
	static Request enter(String site, String body)
	{
		return new Request.Builder().url(BoardEntry.endpoint(site))
			.post(new LazyBody(BoardEntry.TYPE, () -> body.getBytes(StandardCharsets.UTF_8))).build();
	}

	/** The request that takes all of the times of the player whose key is `key` off the boards. */
	static Request remove(String site, String key)
	{
		return new Request.Builder().url(BoardEntry.removeEndpoint(site))
			.post(new LazyBody(BoardEntry.TYPE, () -> BoardEntry.removeBody(key).getBytes(StandardCharsets.UTF_8))).build();
	}

	/** An answer's JSON, or an IOException for one that is too long or none. */
	private static String text(Response response) throws IOException
	{
		ResponseBody body = response.body();
		if (body == null || body.source().request(MAX_ANSWER + 1) || body.source().getBuffer().size() > MAX_ANSWER)
		{
			throw new IOException("The site's answer was not one it gives.");
		}
		return body.source().readUtf8();
	}

	/**
	 * What the site's answer to a wave means for the player, in words for the panel (BoardEntry.said), `asked` being the
	 * name sent; null for an answer that says nothing to tell, such as a refusal, which is dropped without a word as a
	 * shared log's is.
	 */
	static String entered(Gson gson, Response response, String asked)
	{
		if (!response.isSuccessful())
		{
			return null;
		}
		try
		{
			return BoardEntry.said(gson.fromJson(text(response), BoardEntry.Answer.class), asked);
		}
		catch (IOException | RuntimeException ex)
		{
			return null;
		}
	}

	/**
	 * How many waves Remove my times took off, from the site's answer; an IOException in words for the player when it
	 * did not.
	 */
	static int removed(Gson gson, Response response) throws IOException
	{
		if (!response.isSuccessful())
		{
			throw new IOException(response.code() == 429 ? "Too many requests. Try again in a minute."
				: "The site could not remove your times. Try again later.");
		}
		try
		{
			return gson.fromJson(text(response), JsonObject.class).get("removed").getAsInt();
		}
		catch (RuntimeException ex)
		{
			throw new IOException("The site's answer was not one it gives. Try again later.", ex);
		}
	}
}

package nl.dexanddice.solsurvivor;

import java.io.IOException;
import okhttp3.MediaType;
import okhttp3.RequestBody;
import okio.BufferedSink;

/**
 * A request's body made when OkHttp sends it, on OkHttp's own thread, and kept for a retry: the plugin hands a shared
 * wave log or a run to OkHttp from the client thread, and the JSON or the gzip that takes a few milliseconds is made
 * here rather than on the tick, as RuneLite asks of a plugin. What the body is made of must not change after it is
 * handed over: a WaveLog's snapshot, or the past waves' logs. A body that cannot be made fails the call with its
 * IOException, which the call's onFailure gets.
 */
final class LazyBody extends RequestBody
{
	/** How the body's bytes are made. */
	interface Maker
	{
		byte[] make() throws IOException;
	}

	private final MediaType type;
	private Maker maker;
	private byte[] bytes;

	LazyBody(String type, Maker maker)
	{
		this.type = MediaType.parse(type);
		this.maker = maker;
	}

	/** The bytes, made the first time they are asked for: OkHttp asks for the length before it writes them. */
	private synchronized byte[] bytes() throws IOException
	{
		if (bytes == null)
		{
			bytes = maker.make();
			maker = null;
		}
		return bytes;
	}

	@Override
	public MediaType contentType()
	{
		return type;
	}

	@Override
	public long contentLength() throws IOException
	{
		return bytes().length;
	}

	@Override
	public void writeTo(BufferedSink sink) throws IOException
	{
		sink.write(bytes());
	}
}

package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Supplier;
import nl.dexanddice.solsurvivor.core.ReplayLink;
import nl.dexanddice.solsurvivor.core.RunUpload;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * A selected recording only, sent by the plugin's injected RuneLite HTTP client on its background dispatcher. The run's
 * JSON is written and gzipped there too (LazyBody, core.RunUpload), not on the client thread; a run too large for the
 * site fails the call with RunUpload.TooLarge, whose message the player is shown.
 */
final class ReplayUpload
{
	private ReplayUpload()
	{
	}

	/** The upload of the run whose JSON `json` writes, which must be the past waves' logs as they were handed over. */
	static Request request(String site, Supplier<String> json)
	{
		return new Request.Builder().url(ReplayLink.endpoint(site)).post(new LazyBody(RunUpload.TYPE, () -> RunUpload.pack(json.get()))).build();
	}

	/**
	 * The page that opens the stored run, from the site's answer read with RuneLite's Gson: only an ID the site gave, on
	 * the site's own address, so that an answer cannot send the browser elsewhere.
	 */
	static String browserUrl(Gson gson, String site, Response response) throws IOException
	{
		if (!response.isSuccessful())
		{
			String error = response.code() == 429 ? "Too many runs opened. Try again in a minute."
				: response.code() == 413 ? "This run is too large to open. You can still copy its wave logs."
				: response.code() == 400 ? "The site could not read this recording. Update the plugin and try again."
				: "The site could not store this run. Try again.";
			throw new IOException(error);
		}
		ResponseBody body = response.body();
		if (body == null || body.source().request(4097) || body.source().getBuffer().size() > 4096)
		{
			throw new IOException("The site returned an invalid recording link. Try again.");
		}
		try
		{
			JsonObject data = gson.fromJson(body.source().readUtf8(), JsonObject.class);
			return ReplayLink.browser(site, data.get("id").getAsString());
		}
		catch (RuntimeException ex)
		{
			throw new IOException("The site returned an invalid recording link. Try again.", ex);
		}
	}
}

package nl.dexanddice.solsurvivor;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;
import nl.dexanddice.solsurvivor.core.TriangleDot;

@ConfigGroup(SolSurvivorConfig.GROUP)
public interface SolSurvivorConfig extends Config
{
	String GROUP = "solsurvivor";

	@ConfigItem(
		keyName = "copyHotkey",
		name = "Copy link hotkey",
		description = "Copies a link of the arena as it is now.",
		position = 1
	)
	default Keybind copyHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "includeGear",
		name = "Include gear and stats",
		description = "Puts your worn items, weapon, attack style, prayer bonus, prayer points and combat levels in the link, and your gear in the wave log.",
		position = 2
	)
	default boolean includeGear()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatConfirm",
		name = "Say so in chat",
		description = "Puts a line in your chat box when a link is copied, or why it could not be.",
		position = 3
	)
	default boolean chatConfirm()
	{
		return true;
	}

	@ConfigItem(
		keyName = "openOnEntering",
		name = "Open panel on entering",
		description = "Opens this panel as you enter the Fortis Colosseum, and RuneLite's sidebar with it if it is shut. Off, the panel opens only from its sun in the sidebar.",
		position = 4
	)
	default boolean openOnEntering()
	{
		return true;
	}

	String ONLY_AT_COLOSSEUM = "onlyAtColosseum";

	@ConfigItem(
		keyName = ONLY_AT_COLOSSEUM,
		name = "Show only at the Colosseum",
		description = "Shows the plugin's sun in RuneLite's sidebar only in the Fortis Colosseum and its lobby. Past waves are then at hand only there.",
		position = 5
	)
	default boolean onlyAtColosseum()
	{
		return false;
	}

	@ConfigItem(
		keyName = "recordWaveLog",
		name = "Record wave log",
		description = "Keeps the last 25 waves for Past waves: tiles, hitpoints, prayers, attacks, projectiles, hits and optional gear. Nothing uploads unless Upload past runs or Share wave logs is on.",
		position = 6
	)
	default boolean recordWaveLog()
	{
		return true;
	}

	String KEEP_RUNS = "keepRuns";

	@ConfigItem(
		keyName = KEEP_RUNS,
		name = "Keep runs between sessions",
		description = "Saves the waves Record wave log keeps on this computer, in RuneLite's folder for this plugin, each account's apart, so that Past waves still lists them after RuneLite closes. Nothing is sent anywhere. Off, they last until RuneLite closes, and those saved are deleted.",
		position = 7
	)
	default boolean keepRuns()
	{
		return true;
	}

	/**
	 * RuneLite's wording for a setting that sends anything to a server it does not run: each such setting is off by
	 * default and shows it as the player switches it on, as RuneLite's plugin guide asks (runelite/example-plugin's
	 * AGENTS.md), so that the Plugin Hub's listing needs no warning of its own.
	 */
	String SHARE_WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	/** The settings that send something to the site, together, so that the player sees they are off by default. */
	@ConfigSection(
		name = "Sending to the site",
		description = "Off until you switch them on. With Upload past runs and Share wave logs off, the plugin sends nothing to the Sol Survivor site.",
		position = 8
	)
	String sendingSection = "sending";

	@ConfigItem(
		keyName = "uploadPastRuns",
		name = "Upload past runs",
		description = "Lets a past run's Watch button upload the run to the Sol Survivor site, which opens it in your browser to play back: tiles, hitpoints, prayers, hits and your gear with Include gear and stats on, with no account name. Anyone with its link can view it for seven days.",
		warning = SHARE_WARNING,
		position = 1,
		section = sendingSection
	)
	default boolean uploadPastRuns()
	{
		return false;
	}

	@ConfigItem(
		keyName = "shareWaveLogs",
		name = "Share wave logs",
		description = "Sends each wave's log to the Sol Survivor site as the wave ends, so that the planner can be checked against real games, and its Learned ranking trained on how waves start. No account name or combat levels; your gear only with Include gear and stats on. Shown on the site only on its leaderboard, with Leaderboard on, and deleted after 90 days but for the leaderboard's records. Needs Record wave log.",
		warning = SHARE_WARNING,
		position = 2,
		section = sendingSection
	)
	default boolean shareWaveLogs()
	{
		return false;
	}

	/** Whether the player's waves go on the site's leaderboard (core.BoardEntry); off by default. */
	String LEADERBOARD = "leaderboard";

	/**
	 * The warning RuneLite shows as the player switches the leaderboard on: like SHARE_WARNING, and saying that the name
	 * goes up in public, their RuneScape name unless they typed another (the user's choice, 2026-10-26).
	 */
	String LEADERBOARD_WARNING = "This puts your wave times on the Sol Survivor site's public leaderboard under your RuneScape name, or the Leaderboard name you type, on a 3rd-party server not controlled or verified by RuneLite developers";

	@ConfigItem(
		keyName = LEADERBOARD,
		name = "Leaderboard",
		description = "Puts each wave you finish on the Sol Survivor site's leaderboard, timed by the game's own wave clock, where anyone can see it and watch the run: under your RuneScape name, or the Leaderboard name below. Needs Share wave logs.",
		warning = LEADERBOARD_WARNING,
		position = 3,
		section = sendingSection
	)
	default boolean leaderboard()
	{
		return false;
	}

	/** The name the player's times go up under on the leaderboard; blank, their RuneScape name. */
	String LEADERBOARD_NAME = "leaderboardName";

	@ConfigItem(
		keyName = LEADERBOARD_NAME,
		name = "Leaderboard name",
		description = "The name your waves go up under with Leaderboard on. Blank, your RuneScape name. Up to 12 letters, digits, spaces, hyphens or underscores.",
		position = 4,
		section = sendingSection
	)
	default String leaderboardName()
	{
		return "";
	}

	/**
	 * The player's key on the leaderboard (core.BoardEntry): a random secret made the first time a wave goes up, which keeps
	 * the name and the times the player's and lets Remove my times find them; not shown.
	 */
	String LEADERBOARD_KEY = "leaderboardKey";

	@ConfigItem(
		keyName = LEADERBOARD_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default String leaderboardKey()
	{
		return "";
	}

	@ConfigSection(
		name = "Safe / Fast / Easy",
		description = "Where the site's Safe / Fast / Easy triangle starts when you open a wave from the plugin.",
		position = 9,
		closedByDefault = true
	)
	String triangleSection = "triangle";

	@ConfigItem(
		keyName = "setTriangle",
		name = "Set the triangle",
		description = "Opens every wave from the plugin with the triangle's dot where Safe, Fast and Easy below put it, and the plan it suggests. Off, the site keeps the dot where you last left it.",
		position = 1,
		section = triangleSection
	)
	default boolean setTriangle()
	{
		return false;
	}

	@Range(max = TriangleDot.MAX_SHARE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "triangleSafe",
		name = "Safe",
		description = "How much the plan suggested minds the hits you take. Copy the three from the site, as it reads them out under the triangle; they need not add up to 100, as each counts as its share of their total.",
		position = 2,
		section = triangleSection
	)
	default int triangleSafe()
	{
		return 33;
	}

	@Range(max = TriangleDot.MAX_SHARE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "triangleFast",
		name = "Fast",
		description = "How much the plan suggested minds the ticks the wave takes.",
		position = 3,
		section = triangleSection
	)
	default int triangleFast()
	{
		return 33;
	}

	@Range(max = TriangleDot.MAX_SHARE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "triangleEasy",
		name = "Easy",
		description = "How much the plan suggested minds the inputs: prayer switches, clicks and tiles walked.",
		position = 4,
		section = triangleSection
	)
	default int triangleEasy()
	{
		return 33;
	}

	@ConfigSection(
		name = "Prayer reliability",
		description = "Counts your protection prayer flicks, so that the site's Prayer reliability can be your own.",
		position = 10,
		closedByDefault = true
	)
	String prayerSection = "prayer";

	@ConfigItem(
		keyName = "countFlicks",
		name = "Count my flicks",
		description = "Counts each wave's protection prayers against the attacks, on time or late, and puts the newest 60 waves' totals in the links, so that the site's Prayer reliability opens on Mine: as reliable as your flicks show, kept on the safe side. Needs Record wave log. Off, it forgets the waves counted.",
		position = 1,
		section = prayerSection
	)
	default boolean countFlicks()
	{
		return false;
	}

	/** The waves "Count my flicks" counted (core.PrayerRecord.toText), kept here between sessions; not shown. */
	String PRAYER_RECORD = "prayerRecord";

	@ConfigItem(
		keyName = PRAYER_RECORD,
		name = "",
		description = "",
		hidden = true
	)
	default String prayerRecord()
	{
		return "";
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel, in the Sol Survivor site's stone look (design 1, "Stone rows", of the plugin panel designs of
 * 2026-10-25, which the user picked): the site's Setup tab in the sidebar. A raised row for the wave under way, its
 * number in a slot, with the button that opens the arena as it is now on the site, and under it a well with what the
 * last button did. The wave's start is not on that row: the wave's line under Past waves opens it, from the tick the
 * wave starts (the user's choice, 2026-10-25). A row for Minimus's pick, which lights up while he offers his three. Under Past
 * waves, each run a row that folds open and shut like the loot tracker's, onto its waves in a well: a line per wave
 * with small buttons that open it on the site at its start or on the tick its reinforcements came, and copy its log,
 * and on the run's head a button that copies the whole run and one that uploads it to watch it back. With Leaderboard
 * on, a row for the site's leaderboard: the name, its page outside a wave, and Remove my times. The help is in
 * the tooltip of the question mark at the top. Like the rest of the plugin it shows nothing about how to play the
 * wave; the plans are the site's.
 */
class SolSurvivorPanel extends PluginPanel
{
	private boolean replayBusy;

	/** Runs can be rebuilt on a game tick; their Watch buttons keep the upload state. Called on the Swing thread. */
	void showReplayBusy(boolean busy)
	{
		replayBusy = busy;
		buildRuns();
	}

	/** What the panel's buttons do, which the plugin carries out on the client thread. */
	interface Actions
	{
		void openNow();

		void openRecommender();

		/** Open the logged wave `id` on the site at its first tick. */
		void openPastStart(int id);

		/** Open the logged wave `id` on the site on the tick its reinforcements came. */
		void openPastReinforcements(int id);

		void copyWaveLog(int id);

		/** Copy the whole run that holds the logged wave `id`. */
		void copyRun(int id);

		/** Upload the selected run and open its recording directly in the browser. */
		void openPastRun(int id);

		/** Open the site's leaderboard in the browser. */
		void openLeaderboard();

		/** Take every time of the player's off the leaderboard, once they confirmed it. */
		void removeTimes();
	}

	/** A logged wave, as its line shows it. */
	static final class WaveRow
	{
		private final int id;
		private final int wave;
		private final String detail;
		private final boolean underWay;
		private final boolean start;
		private final boolean reinforcements;

		/**
		 * `detail`: how the wave went, or that it is under way, which `underWay` marks in gold. `start` and
		 * `reinforcements`: whether the log kept the wave's state on its first tick and when they came.
		 */
		WaveRow(int id, int wave, String detail, boolean underWay, boolean start, boolean reinforcements)
		{
			this.id = id;
			this.wave = wave;
			this.detail = detail;
			this.underWay = underWay;
			this.start = start;
			this.reinforcements = reinforcements;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof WaveRow))
			{
				return false;
			}
			WaveRow r = (WaveRow) o;
			return r.id == id && r.wave == wave && r.detail.equals(detail) && r.underWay == underWay && r.start == start
				&& r.reinforcements == reinforcements;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(id, wave, detail, underWay, start, reinforcements);
		}
	}

	/**
	 * A run's row: its key, the id of its first wave's log, which stays as the run grows; its name, such as "Latest run";
	 * the line under it, such as "Waves 1–5 · 5:11"; the glory its waves completed earned, such as "5,526 glory", on a
	 * line of its own so that the run's line keeps clear of its buttons, or null when none is known; and its waves,
	 * newest first.
	 */
	static final class RunGroup
	{
		private final int key;
		private final String name;
		private final String detail;
		private final String glory;
		private final List<WaveRow> waves;

		RunGroup(int key, String name, String detail, String glory, List<WaveRow> waves)
		{
			this.key = key;
			this.name = name;
			this.detail = detail;
			this.glory = glory;
			this.waves = waves;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof RunGroup))
			{
				return false;
			}
			RunGroup r = (RunGroup) o;
			return r.key == key && r.name.equals(name) && r.detail.equals(detail) && Objects.equals(r.glory, glory)
				&& r.waves.equals(waves);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(key, name, detail, glory, waves);
		}
	}

	/** The help, in the tooltip of the question mark beside the panel's title. */
	private static final String HELP = "Arena now opens the wave on the Sol Survivor site as it is now, and copies its link. "
		+ "Modifier pick opens Minimus's three offers there while he makes them. Under Past waves, a wave's buttons open it at "
		+ "its start, the wave under way too, or on the tick its reinforcements came, and copy its log to paste into the site. "
		+ "With Upload past runs on in the settings, Watch uploads that run's tiles, hitpoints, prayers, hits and recorded gear "
		+ "to the site, where anyone with its link can view it for seven days. With Share wave logs on, each wave's log goes to "
		+ "the site, without your levels, as the wave ends, and with Leaderboard on too, each wave you finish goes on "
		+ "the site's leaderboard under your RuneScape name or the name you set. All are off until you turn them on. This plugin draws nothing in the game.";

	private static final ImageIcon SUN = Stone.sun(24);
	/** Yellow, as the text of the primary button it sits on. */
	private static final ImageIcon ARENA = Stone.arena(12, Stone.YELLOW);
	private static final ImageIcon CARDS_ON = Stone.cards(24, Stone.GOLD);
	private static final ImageIcon CARDS_OFF = Stone.cards(24, Stone.DIM);
	private static final ImageIcon START_ICON = Stone.play(10, Stone.ORANGE);
	private static final ImageIcon REINFORCEMENTS_ICON = Stone.figures(12, Stone.ORANGE);
	private static final ImageIcon COPY_ICON = Stone.copy(11, Stone.MUTED);
	private static final ImageIcon COPY_RUN_ICON = Stone.copy(12, Stone.MUTED);
	private static final ImageIcon WATCH_ICON = Stone.replay(12, Stone.ORANGE);
	private static final ImageIcon OPEN_ICON = Stone.caret(9, Stone.MUTED, true);
	private static final ImageIcon SHUT_ICON = Stone.caret(9, Stone.MUTED, false);

	private final Actions actions;
	private final Stone.Slot waveSlot = new Stone.Slot(34, SUN);
	private final JLabel waveTitle = new Stone.Shadowed("", bold(), Stone.ORANGE);
	private final JLabel waveState = label("", small(), Stone.TEXT);
	private final Stone.Button openNow = new Stone.Button("Arena now", ARENA, true, small(), 7, 6);
	private final Stone.Well resultWell = new Stone.Well(new BorderLayout(), 4, 5, 4, 5);
	private final JLabel result = label("", small(), Stone.TEXT);
	private final Stone.Row pickRow = new Stone.Row(new BorderLayout(8, 0), 5, 5, 5, 6);
	private final Stone.Slot pickSlot = new Stone.Slot(34, CARDS_OFF);
	private final JLabel pickState = label("", small(), Stone.MUTED);
	private final Stone.Button openRecommender = new Stone.Button("Open", null, true, small(), 7, 6);
	/** The leaderboard's row, while Leaderboard is on or the player has times to remove (showBoard). */
