package nl.dexanddice.solsurvivor.core;

/**
 * The game's own counters for the wave and the run under way, which the wave log keeps on the wave's first tick and on
 * each tick one changes (WaveLogWriter's `counters`): each is a varp or a varbit, by the id RuneLite's gameval names it
 * by (VarPlayerID, VarbitID), and its key in the log is that name in camel case without COLOSSEUM_. What each holds is
 * the game's to say and the logs' to show: nothing in the plugin or on the site reads them yet. They are there so that
 * the logs can check the planner's Doom count and price a wave in the game's own glory.
 *
 * Only the counters of the wave and the run under way are logged: none of the account's own, such as its best glory or
 * waves completed, which the hiscores could tie to the player in a shared log. A shared log leaves out the wave's start
 * time and the run's total duration too (`shared`): nobody has seen what they hold, and a count of the world's ticks
 * would date the wave, which the Privacy page says a shared log does not. Copy wave log keeps them.
 */
public enum ColosseumCounter
{
	/** Doom's stacks on the player: VarbitID.COLOSSEUM_DOOM_STACKS_CLIENT. */
	DOOM_STACKS("doomStacks", true, 9801, true),
	/** VarPlayerID.COLOSSEUM_CURRENT_GLORY. */
	CURRENT_GLORY("currentGlory", false, 4132, true),
	/** VarPlayerID.COLOSSEUM_WAVE_START_TIME: not shared. */
	WAVE_START_TIME("waveStartTime", false, 4133, false),
	/** VarPlayerID.COLOSSEUM_WAVE_DAMAGE_TAKEN. */
	WAVE_DAMAGE_TAKEN("waveDamageTaken", false, 4134, true),
	/** VarPlayerID.COLOSSEUM_LAST_MODIFIER_GLORY. */
	LAST_MODIFIER_GLORY("lastModifierGlory", false, 4135, true),
	/** VarPlayerID.COLOSSEUM_LAST_WAVE_DURATION. */
	LAST_WAVE_DURATION("lastWaveDuration", false, 4136, true),
	/** VarPlayerID.COLOSSEUM_TOTAL_DURATION: not shared. */
	TOTAL_DURATION("totalDuration", false, 4137, false);

	private final String key;
	private final boolean varbit;
	private final int id;
	private final boolean shared;

	ColosseumCounter(String key, boolean varbit, int id, boolean shared)
	{
		this.key = key;
		this.varbit = varbit;
		this.id = id;
		this.shared = shared;
	}

	/** Its key in the log's `counters`. */
	public String getKey()
	{
		return key;
	}

	/** Whether it is a varbit; else it is a varp. */
	public boolean isVarbit()
	{
		return varbit;
	}

	/** The game's id for the varbit or the varp. */
	public int getId()
	{
		return id;
	}

	/** Whether a shared log (WaveLogWriter.toShare) holds it. */
	public boolean isShared()
	{
		return shared;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the plugin remembers of a Colosseum run between ticks, fed the game's events by the RuneLite layer and free of
 * RuneLite itself, so that its tests run on mocked game data. It follows the wave from the game's chat messages, which
 * NPCs spawned after the wave's first tick (the reinforcements), the orbs each Manticore has shown, each NPC's attacks
 * and health bar, the hits that dealt the player damage this wave (Doom's stacks), the molten sand on the floor, and the
 * modifiers taken; capture() turns that and the NPCs and player of a tick into an ArenaState.
 *
 * It only reads: nothing here, or in the plugin, acts on the game or draws in it.
 */
public final class ColosseumTracker
{
	/** The last wave Sol Survivor plans: wave 12 is Sol Heredit. */
	public static final int LAST_WAVE = 11;

	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern WAVE_START = Pattern.compile("Wave: (\\d+)");
	private static final Pattern WAVE_DONE = Pattern.compile("Wave (\\d+) completed!");
	private static final String SOL_START = "Sol Heredit jumps down from his seat";

	/**
	 * The graphic on a Javelin Colossus's special's landing tile as it lands (RuneLite's SpotanimID
	 * WILD_FALLOFF_METEOR_BLAST_RED), with Reentry or without: in the user's logs it comes on the tile of the shadow, three
	 * ticks after it.
	 */
	public static final int JAVELIN_LANDING_GRAPHIC = 2265;
	/** Molten Sand, the scenery that Reentry's and Volatility III's sand is (the OSRS Wiki's Molten Sand page). */
	public static final int MOLTEN_SAND_ID = 50746;
	/** A hitsplat that heals (RuneLite's HitsplatID.HEAL). */
	public static final int HEAL_HITSPLAT = 6;
	/**
	 * The hitsplats with an amount that is not damage taken, by RuneLite's HitsplatID: a heal, the cyan ones, a prayer
	 * drain, sanity's drain and restore, and Doom's own. Any other with an amount above 0 counts as a stack of Doom.
	 */
	private static final Set<Integer> NOT_DAMAGE = new HashSet<>(Arrays.asList(HEAL_HITSPLAT, 11, 15, 60, 71, 72, 73));
	/**
	 * The tiles a Javelin special's landing turns to sand at each Reentry tier, 0 to 3, as [dx, dy] from the landing tile:
	 * the site's REENTRY_SAND_OFFSETS (src/data/calibration.ts), from the wiki, unconfirmed in game.
	 */
	private static final int[][][] SAND_OFFSETS = {{}, {{0, 0}}, {{0, 0}, {-1, 1}}, {{0, 0}, {-1, 1}, {-1, 0}}};

	private Integer wave;
	private boolean waveStarted;
	private int waveStartTick = -1;

	/** The NPCs, by index, that spawned after their wave's first tick. */
	private final Set<Integer> reinforcements = new HashSet<>();
	/** Whether a reinforcement has come this wave, even one that has since died. */
	private boolean reinforcementsArrived;
	private final Map<Integer, OrbOrder> orbs = new HashMap<>();
	/** The tick each NPC's last attack animation started on, by index. */
	private final Map<Integer, Integer> lastAttack = new HashMap<>();
	/**
	 * The attacks each NPC has made, by index, for those whose count is known: it spawned while the plugin watched, or for
	 * a Javelin Colossus the plugin saw a special. Kept across the wave's start, since the game may spawn the wave's NPCs
	 * before or after its message on the same tick; an NPC's despawn clears its entries.
	 */
	private final Map<Integer, Integer> attackCounts = new HashMap<>();
	/** Each NPC's health bar as the game last showed it, [ratio, scale], by index; an NPC's despawn or a heal clears it. */
	private final Map<Integer, int[]> healthBars = new HashMap<>();
	/** The hitsplats on the player that dealt damage since the wave the plugin saw start: Doom's stacks. */
	private int damageTaken;
	/**
	 * The most the game's wave damage counter read in the wave under way or the one just finished (RunWave's `damage`),
	 * from the tick after the wave's first: on that first tick the counter may still hold the last wave's.
	 */
	private int waveDamage;
	/** Whether the next run tick is the first of the wave, whose damage counter is not read (waveDamage). */
	private boolean freshWave;
	/** The sand the Javelins' landings laid this wave below Reentry II, which goes when the wave does. */
	private final Set<GridTile> waveSand = new LinkedHashSet<>();
	/** The sand they laid at Reentry II or III, which lasts the run. */
	private final Set<GridTile> lastingSand = new LinkedHashSet<>();
	/** The Molten Sand objects in the scene, by tile, each with how many stand there. */
	private final Map<GridTile, Integer> sandObjects = new LinkedHashMap<>();

	private final Set<Modifier> taken = EnumSet.noneOf(Modifier.class);
	private boolean modifiersComplete;
	private final List<Modifier> options = new ArrayList<>(3);

	/** The waves of the run finished so far, oldest first, for the pick link (RunWave). */
	private final List<RunWave> run = new ArrayList<>();
	/**
	 * A wave the game just said was completed, until the next tick (onRunTick) adds it to the run with the modifiers held:
	 * its number, its ticks and whether it hurt the player, the last two null when the plugin did not see it start.
	 */
	private Integer doneWave;
	private Integer doneTicks;
	private Boolean doneHit;

	/** Forget the run: the player left the Colosseum, hopped or logged out. */
	public void reset()
	{
		wave = null;
		waveStarted = false;
		waveStartTick = -1;
		taken.clear();
		modifiersComplete = false;
		options.clear();
		lastAttack.clear();
		attackCounts.clear();
		healthBars.clear();
		lastingSand.clear();
		sandObjects.clear();
		run.clear();
		doneWave = null;
		waveDamage = 0;
		freshWave = false;
		resetWave();
	}

	/**
	 * A wave starts or ends: its reinforcements, orbs and Doom stacks go (the wiki: Doom's stacks clear at the end of the
	 * wave), and so does the sand laid below Reentry II (the wiki's Javelin Colossus page).
	 */
	private void resetWave()
	{
		reinforcements.clear();
		reinforcementsArrived = false;
		orbs.clear();
		damageTaken = 0;
		waveSand.clear();
	}

	/** A game message, on the tick it came. */
	public void onGameMessage(String message, int tick)
	{
		String text = TAG.matcher(message).replaceAll("");
		Matcher m;
		if (text.contains(SOL_START))
		{
			startWave(LAST_WAVE + 1, tick);
		}
		else if ((m = WAVE_START.matcher(text)).find())
		{
			startWave(Integer.parseInt(m.group(1)), tick);
		}
		else if ((m = WAVE_DONE.matcher(text)).find())
		{
			int done = Integer.parseInt(m.group(1));
			boolean seen = waveStarted && wave != null && wave == done;
			doneWave = done;
			doneTicks = seen ? Integer.valueOf(tick - waveStartTick + 1) : null;
			doneHit = seen ? Boolean.valueOf(damageTaken > 0) : null;
			wave = done + 1;
			waveStarted = false;
			resetWave();
		}
	}

	private void startWave(int number, int tick)
	{
		// Wave 1, or a wave the run has already finished, starts a new run.
		if (number == 1 || (!run.isEmpty() && number <= run.get(run.size() - 1).getWave()))
		{
			run.clear();
		}
		wave = number;
		waveStarted = true;
		waveStartTick = tick;
		waveDamage = 0;
		freshWave = true;
		resetWave();
	}

	/** Whether this tick is the first of a wave the plugin saw start. */
	public boolean isWaveStartTick(int tick)
	{
		return waveStarted && tick == waveStartTick;
	}

	/** Whether a wave is under way that the plugin saw start. */
	public boolean isWaveStarted()
	{
		return waveStarted;
	}

	/** Whether a reinforcement has spawned in the wave under way, even one that has since died. */
	public boolean isReinforcementsArrived()
	{
		return reinforcementsArrived;
	}

	/** The wave under way, or the next one between waves; null when the plugin has not seen a wave's message yet. */
	public Integer getWave()
	{
		return wave;
	}

	/**
	 * Each tick in the Colosseum, with the modifiers' varbits and the game's current glory and wave damage counters: a
	 * wave the game has just said was completed joins the run with the modifiers held through it, and until the next wave
	 * starts the last wave finished takes the glory counter as it reads and the most the damage counter has read, since
	 * when the game updates and clears them is not known.
	 */
	public void onRunTick(ModifierLevels levels, int glory, int damage)
	{
		if (waveStarted && freshWave)
		{
			freshWave = false;
		}
		else if (waveStarted)
		{
			waveDamage = Math.max(waveDamage, damage);
		}
		if (doneWave != null)
		{
			int done = doneWave;
			run.removeIf(w -> w.getWave() >= done);
			run.add(new RunWave(done, doneTicks, doneHit, doneTicks == null ? null : Math.max(waveDamage, damage), modifiers(levels), glory));
			doneWave = null;
		}
		else if (!waveStarted && !run.isEmpty())
		{
			run.set(run.size() - 1, run.get(run.size() - 1).withCounters(glory, damage));
		}
	}

	/** The waves of the run finished so far, oldest first: none before the first, or after leaving the Colosseum. */
	public List<RunWave> getRun()
	{
		return Collections.unmodifiableList(new ArrayList<>(run));
	}

	/** Whether the modifiers taken are all known: see ArenaState.isModifiersComplete. */
	public boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	/** An NPC spawned, on the tick it did. One that spawns after its wave's first tick is a reinforcement. */
	public void onNpcSpawned(int index, int npcId, int tick)
	{
		if (NpcKind.forNpcId(npcId, false) == null)
		{
			return;
		}
		if (waveStarted && tick != waveStartTick)
		{
			reinforcements.add(index);
			reinforcementsArrived = true;
		}
		if (npcId == NpcKind.MANTICORE_ID)
		{
			orbs.put(index, new OrbOrder());
		}
		else
		{
			lastAttack.remove(index);
			attackCounts.put(index, 0);
		}
	}

	public void onNpcDespawned(int index)
	{
		reinforcements.remove(index);
		orbs.remove(index);
		lastAttack.remove(index);
		attackCounts.remove(index);
		healthBars.remove(index);
	}

	/**
	 * An NPC's health bar on this tick: its ratio of `scale`, or a ratio below 0 while the game hides the bar, which it
	 * does some ticks after the last hit. The last bar shown is kept until the NPC despawns or is healed: in the user's
	 * logs no bar came back higher after it hid, for up to 71 ticks, so the NPCs did not heal unseen in that time.
	 */
	public void onHealthBar(int index, int ratio, int scale)
	{
		if (ratio >= 0 && scale > 0 && ratio <= scale)
		{
			healthBars.put(index, new int[] {ratio, scale});
		}
	}

	/**
	 * A hitsplat on an NPC. A heal forgets its bar, which no longer says how hurt it is, until the game shows the bar again:
	 * the link then gives the NPC at full health rather than more hurt than it is.
	 */
	public void onNpcHit(int index, int amount, int type)
	{
		if (type == HEAL_HITSPLAT)
		{
			healthBars.remove(index);
		}
	}

	/**
	 * A hitsplat on the player. Doom's stacks are the hits that dealt damage in the wave (the wiki: a stack for each
	 * instance of damage taken), so each one with an amount above 0 counts, while a wave the plugin saw start is under
	 * way; a block, a heal or a drain does not (NOT_DAMAGE). Which hitsplats the game counts is unconfirmed: those of
	 * Reentry's sand and Solarflare count here, as the site's Doom counts them.
	 */
	public void onPlayerHit(int amount, int type)
	{
		if (waveStarted && amount > 0 && !NOT_DAMAGE.contains(type))
		{
			damageTaken++;
		}
	}

	/**
	 * A graphic on a tile, with Reentry's tier at the time. A Javelin special landing under Reentry lays sand on its tile
	 * and, from tier II, the tiles SAND_OFFSETS adds, those on the grid: below tier II for the rest of the wave, from it
	 * for good. A tile the game moves to another, when one is a wall or a pillar, is not known here; the Molten Sand
	 * objects show it, if they show at all.
	 */
	public void onTileGraphic(GridTile tile, int graphicId, int reentryTier)
	{
		if (graphicId != JAVELIN_LANDING_GRAPHIC || tile == null || reentryTier < 1 || reentryTier > 3)
		{
			return;
		}
		for (int[] offset : SAND_OFFSETS[reentryTier])
		{
			GridTile sand = new GridTile(tile.getX() + offset[0], tile.getY() + offset[1]);
			if (ArenaGeometry.onGrid(sand))
			{
				(reentryTier >= 2 ? lastingSand : waveSand).add(sand);
			}
		}
	}

	/** A Molten Sand object came into the scene on `tile`, or left it; any other object is ignored by the caller. */
	public void onSandObject(GridTile tile, boolean spawned)
	{
		if (tile == null || !ArenaGeometry.onGrid(tile))
		{
			return;
		}
		int count = sandObjects.getOrDefault(tile, 0) + (spawned ? 1 : -1);
		if (count > 0)
		{
			sandObjects.put(tile, count);
		}
		else
		{
			sandObjects.remove(tile);
		}
	}

	/** The scene is loading again, which spawns its objects anew: the Molten Sand objects are counted from there. */
	public void onSceneLoading()
	{
		sandObjects.clear();
	}

	/**
	 * An NPC started an animation, on the tick it did. An attack (AttackAnimations, unconfirmed) restarts its attack timer
	 * and adds to its count. A Javelin Colossus's special is its 5th attack (JAVELIN_SPECIAL_EVERY on the site), so it
	 * sets the count to the next multiple of 5, which fixes the phase of its specials even when the plugin missed its
	 * spawn.
	 */
	public void onNpcAnimation(int index, int npcId, int animationId, int tick)
	{
		if (!AttackAnimations.isAttack(npcId, animationId))
		{
			return;
		}
		lastAttack.put(index, tick);
		Integer count = attackCounts.get(index);
		if (AttackAnimations.isSpecial(npcId, animationId))
		{
			int next = count == null ? 1 : count + 1;
			attackCounts.put(index, (next + 4) / 5 * 5);
		}
		else if (count != null)
		{
			attackCounts.put(index, count + 1);
		}
	}

	/** An orb graphic on a Manticore this tick. */
	public void onOrb(int index, OrbStyle style)
	{
		orbs.computeIfAbsent(index, i -> new OrbOrder()).see(style);
	}

	/**
	 * The modifier selector opened between waves: the game ids of the three on offer, and the mask of those already taken,
	 * which settles every modifier taken so far.
	 */
	public void onModifierOptions(int first, int second, int third, int takenMask)
	{
		options.clear();
		options.add(Modifier.forId(first));
		options.add(Modifier.forId(second));
		options.add(Modifier.forId(third));
		taken.addAll(Modifier.forMask(takenMask));
		modifiersComplete = true;
	}

	/**
	 * The three modifiers the selector offers while it is open, in its order, each null for an id this plugin does not
	 * know; empty while it is closed.
	 */
	public List<Modifier> getOptions()
	{
		return Collections.unmodifiableList(new ArrayList<>(options));
	}

	/** The selector closed with the option at `choice`, 1 to 3; 0 when none was picked. */
	public void onModifierChosen(int choice)
	{
		if (choice >= 1 && choice <= options.size() && options.get(choice - 1) != null)
		{
			taken.add(options.get(choice - 1));
		}
		options.clear();
	}

	/**
	 * The arena on this tick: the NPCs the game shows, the player's tile and the modifiers' tiers, with what the tracker
	 * remembers. An ExportException says why there is nothing to export, such as no NPCs or Sol Heredit's wave.
	 */
	public ArenaState capture(int tick, GridTile player, List<SeenNpc> seen, ModifierLevels levels) throws ExportException
	{
		if (wave != null && wave > LAST_WAVE)
		{
			throw new ExportException("Sol Survivor plans waves 1 to 11, not Sol Heredit's.");
		}
		if (player == null || !ArenaGeometry.onGrid(player))
		{
			throw new ExportException("You are not in the Colosseum's arena.");
		}

		Map<Modifier, Integer> modifiers = modifiers(levels);
		boolean mm3 = Integer.valueOf(3).equals(modifiers.get(Modifier.MANTIMAYHEM));
		boolean waveStart = isWaveStartTick(tick);

		List<ExportNpc> npcs = new ArrayList<>();
		List<GridTile> solarflareOrbs = new ArrayList<>();
		boolean arrived = reinforcementsArrived;
		for (SeenNpc n : seen)
		{
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID && ArenaGeometry.onGrid(n.getTile()))
			{
				solarflareOrbs.add(n.getTile());
				continue;
			}
			NpcKind kind = NpcKind.forNpcId(n.getNpcId(), isReinforcement(n));
			if (kind == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			// The Jaguar, the Minotaur and the second shaman only ever come as reinforcements.
			arrived |= kind == NpcKind.JAGUAR_WARRIOR || kind == NpcKind.MINOTAUR || kind == NpcKind.REINFORCEMENT_SHAMAN;
			String code = null;
			Integer sinceAttack = null;
			Integer attacks = null;
			if (kind == NpcKind.MANTICORE)
			{
				OrbOrder order = orbs.get(n.getIndex());
				code = order == null ? "u" : order.losCode(mm3);
			}
			else if (!waveStart)
			{
				Integer last = lastAttack.get(n.getIndex());
				sinceAttack = last == null ? null : Integer.valueOf(tick - last);
				attacks = attackCounts.get(n.getIndex());
			}
			// Mid-wave only: at its start every NPC is at full health.
			int[] health = waveStart ? null : healthBars.get(n.getIndex());
			npcs.add(new ExportNpc(kind, n.getTile(), code, sinceAttack, attacks, health));
		}
		if (npcs.isEmpty())
		{
			throw new ExportException("There are no NPCs in the arena to export.");
		}

		Integer waveTick = waveStarted && !waveStart ? Integer.valueOf(tick - waveStartTick) : null;
		// Doom's stacks only when the plugin saw every hit of the wave, from its start.
		Integer doomStacks = waveStarted && !waveStart && modifiers.containsKey(Modifier.DOOM) ? Integer.valueOf(damageTaken) : null;
		return new ArenaState(npcs, player, waveStart, waveStarted ? wave : null, waveTick, !waveStart && arrived, modifiers, modifiersComplete,
			solarflareOrbs, doomStacks, sand());
	}

	/**
	 * The molten sand on the floor: that the Javelins' landings laid (onTileGraphic), lasting sand first, and the tiles of
	 * the Molten Sand objects, each tile once. How long a tile has left is not sent: below Reentry II it lasts the wave,
	 * and from it the run, which is what the site models.
	 */
	private List<GridTile> sand()
	{
		Set<GridTile> tiles = new LinkedHashSet<>(lastingSand);
		tiles.addAll(waveSand);
		tiles.addAll(sandObjects.keySet());
		return new ArrayList<>(tiles);
	}

	/**
	 * Whether an NPC came as a reinforcement: it spawned after its wave's first tick. A shaman already there when the
	 * plugin started is the reinforcement one from wave 7 on, where no wave starts with a shaman; before, it is taken for
	 * the wave's own.
	 */
	private boolean isReinforcement(SeenNpc n)
	{
		if (reinforcements.contains(n.getIndex()))
		{
			return true;
		}
		return n.getNpcId() == NpcKind.SHAMAN_ID && wave != null && wave >= 7;
	}

	/** The modifiers taken, with their tiers: those with tiers by their varbits. The wave log names them too. */
	public Map<Modifier, Integer> modifiers(ModifierLevels levels)
	{
		Map<Modifier, Integer> out = new EnumMap<>(Modifier.class);
		for (Modifier m : Modifier.values())
		{
			if (m.hasTiers())
			{
				int level = Math.max(0, Math.min(3, levels.level(m)));
				// A modifier the selector says is taken is at tier I at least, whatever its varbit reads.
				if (level == 0 && taken.contains(m))
				{
					level = 1;
				}
				if (level > 0)
				{
					out.put(m, level);
				}
			}
			else if (taken.contains(m))
			{
				out.put(m, 1);
			}
		}
		return out;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The player's gear and stats as the game shows them (design spec, "Equipment"): each worn item by its slot, with its id,
 * name and quantity; the weapon's attack speed in ticks, its category and the attack style picked, as the game numbers
 * them; the items in the inventory that can be worn, the switches a player brings; each item's attack and strength bonuses; each worn item's defence bonuses; the gear's prayer bonus; the prayer points now; each combat skill's boosted and real level; and the flags of the offensive prayers that need more than levels. The site maps
 * them to its kill table; the plugin passes on what the game says and works nothing out.
 */
public final class Equipment
{
	/** A worn item. */
	public static final class Item
	{
		private final int id;
		private final String name;
		private final int quantity;

		public Item(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}

		public int getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}

	/** An item in the inventory that can be worn, the slot it goes in, and a weapon's attack speed in ticks (0 unknown). */
	public static final class Switch
	{
		private final String slot;
		private final Item item;
		private final int speed;

		public Switch(String slot, Item item, int speed)
		{
			this.slot = slot;
			this.item = item;
			this.speed = speed;
		}

		public int getSpeed()
		{
			return speed;
		}

		public String getSlot()
		{
			return slot;
		}

		public Item getItem()
		{
			return item;
		}
	}

	/** The numbers an item's bonuses hold (bonuses). */
	public static final int BONUS_COUNT = 9;

	/** The numbers an item's defence bonuses hold (defences). */
	public static final int DEFENCE_COUNT = 5;

	/** The most switches kept: the inventory's 28 places. */
	public static final int MAX_SWITCHES = 28;

	/** The names of the prayer unlock flags (unlocks), in the order they are given and written. */
	public static final String[] UNLOCK_FLAGS = {"rigour", "augury", "deadeye", "mysticVigour", "knightWaves", "zeal"};

	private final Map<String, Item> items = new LinkedHashMap<>();
	private final List<Switch> switches = new ArrayList<>();
	private final Map<String, int[]> stats = new LinkedHashMap<>();
	private final Map<Integer, int[]> bonuses = new LinkedHashMap<>();
	private final Map<Integer, int[]> defences = new LinkedHashMap<>();
	private int weaponSpeed;
	private int weaponCategory;
	private int attackStyle;
	private final List<String> styleNames = new ArrayList<>();
	private int prayerBonus;
	private int prayerPoints;
	private int[] unlocks;

	/** An item worn in a slot, by the slot's name in lower case, such as "weapon" or "ammo". */
	public Equipment item(String slot, Item item)
	{
		items.put(slot, item);
		return this;
	}

	/**
	 * An item in the inventory that can be worn, by the slot it goes in, in the inventory's order; past MAX_SWITCHES it is
	 * passed over.
	 */
	public Equipment switchItem(String slot, Item item)
	{
		return switchItem(slot, item, 0);
	}

	/** A weapon in the inventory, with its attack speed in ticks (0 unknown). */
	public Equipment switchItem(String slot, Item item, int speed)
	{
		if (switches.size() < MAX_SWITCHES)
		{
			switches.add(new Switch(slot, item, speed));
		}
		return this;
	}

	/**
	 * An item's bonuses, by its id: stab, slash, crush, magic and ranged attack, melee and ranged strength, magic damage
	 * in tenths of a percent, and 1 when it takes both hands, else 0. The site works out kill times from them.
	 */
	public Equipment bonuses(int id, int[] values)
	{
		if (values.length != BONUS_COUNT)
		{
			throw new IllegalArgumentException("expected " + BONUS_COUNT + " bonuses, not " + values.length);
		}
		bonuses.put(id, values.clone());
		return this;
	}

	/**
	 * A worn item's defence bonuses, by its id: stab, slash, crush, magic and ranged. With the Defence and Magic levels
	 * the site works out how often the NPCs' attacks land on the player. Apart from bonuses, which the site's readers
	 * before plugin 0.5.0 take only at nine numbers an item.
	 */
	public Equipment defences(int id, int[] values)
	{
		if (values.length != DEFENCE_COUNT)
		{
			throw new IllegalArgumentException("expected " + DEFENCE_COUNT + " defence bonuses, not " + values.length);
		}
		defences.put(id, values.clone());
		return this;
	}

	/** A skill's boosted and real level, by the skill's name in lower case, such as "ranged". */
	public Equipment stat(String skill, int boosted, int real)
	{
		stats.put(skill, new int[]{boosted, real});
		return this;
	}

	/** The weapon's attack speed in ticks (0 when unknown), its category varbit and the attack style varp. */
	public Equipment weapon(int speed, int category, int style)
	{
		this.weaponSpeed = speed;
		this.weaponCategory = category;
		this.attackStyle = style;
		return this;
	}

	/**
	 * The names the game's data gives the weapon's combat options, in attackStyle's order ("Ranging", "Longrange", and
	 * "Other" for an empty place), which tell the site which style is picked.
	 */
	public Equipment styleNames(List<String> names)
	{
		styleNames.clear();
		styleNames.addAll(names);
		return this;
	}

	/** The gear's prayer bonus, summed over the worn items, and the prayer points now. */
	public Equipment prayer(int bonus, int points)
	{
		this.prayerBonus = bonus;
		this.prayerPoints = points;
		return this;
	}

	/**
	 * The flags of the offensive prayers that need more than levels, as the game's varbits hold them: Rigour's, Augury's,
	 * Deadeye's and Mystic Vigour's unlocks, the state of the Knight Waves Training Grounds, which Piety and Chivalry need
	 * finished, and Zeal's unlock, from the Horn of Bran; none of the unlocks is 0 once the prayer is unlocked. The site
	 * works out from them, with the Prayer, Defence, Attack and Strength levels, which prayers the kill times take (its
	 * src/viewer/offensivePrayers.ts).
	 */
	public Equipment unlocks(int rigour, int augury, int deadeye, int mysticVigour, int knightWaves, int zeal)
	{
		this.unlocks = new int[]{rigour, augury, deadeye, mysticVigour, knightWaves, zeal};
		return this;
	}

	/**
	 * A copy without what could point to the player's account, for the wave log they share (WaveShare): the skills'
	 * levels and the prayer unlock flags are left out, and the gear, its bonuses and the prayer points stay as they are.
	 */
	public Equipment withoutLevels()
	{
		Equipment copy = new Equipment();
		copy.items.putAll(items);
		copy.switches.addAll(switches);
		copy.bonuses.putAll(bonuses);
		copy.defences.putAll(defences);
		copy.weaponSpeed = weaponSpeed;
		copy.weaponCategory = weaponCategory;
		copy.attackStyle = attackStyle;
		copy.styleNames.addAll(styleNames);
		copy.prayerBonus = prayerBonus;
		copy.prayerPoints = prayerPoints;
		return copy;
	}

	public Map<String, Item> getItems()
	{
		return Collections.unmodifiableMap(items);
	}

	public List<Switch> getSwitches()
	{
		return Collections.unmodifiableList(switches);
	}

	public Map<Integer, int[]> getBonuses()
	{
		return Collections.unmodifiableMap(bonuses);
	}

	public Map<Integer, int[]> getDefences()
	{
		return Collections.unmodifiableMap(defences);
	}

	public Map<String, int[]> getStats()
	{
		return Collections.unmodifiableMap(stats);
	}

	public int getWeaponSpeed()
	{
		return weaponSpeed;
	}

	public int getWeaponCategory()
	{
		return weaponCategory;
	}

	public int getAttackStyle()
	{
		return attackStyle;
	}

	public List<String> getStyleNames()
	{
		return Collections.unmodifiableList(styleNames);
	}

	public int getPrayerBonus()
	{
		return prayerBonus;
	}

	public int getPrayerPoints()
	{
		return prayerPoints;
	}

	/** The prayer unlock flags in UNLOCK_FLAGS's order, or null when they were not read. */
	public int[] getUnlocks()
	{
		return unlocks == null ? null : unlocks.clone();
	}
}

package nl.dexanddice.solsurvivor.core;

/** Why the arena cannot be exported now: the message says so in words the player can act on. */
public class ExportException extends Exception
{
	public ExportException(String message)
	{
		super(message);
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * An NPC as the state link holds it: its kind, its south-west tile and, for a Manticore, its orb code; what the plugin
 * saw of its attacks, for the link's `attacks`; and its health bar as the game last showed it, for the link's `health`.
 */
public final class ExportNpc
{
	private final NpcKind kind;
	private final GridTile tile;
	private final String orbs;
	private final Integer sinceAttack;
	private final Integer attacks;
	private final int[] health;

	public ExportNpc(NpcKind kind, GridTile tile, String orbs)
	{
		this(kind, tile, orbs, null, null, null);
	}

	public ExportNpc(NpcKind kind, GridTile tile, String orbs, Integer sinceAttack, Integer attacks)
	{
		this(kind, tile, orbs, sinceAttack, attacks, null);
	}

	public ExportNpc(NpcKind kind, GridTile tile, String orbs, Integer sinceAttack, Integer attacks, int[] health)
	{
		this.kind = kind;
		this.tile = tile;
		this.orbs = orbs;
		this.sinceAttack = sinceAttack;
		this.attacks = attacks;
		this.health = health == null ? null : health.clone();
	}

	/**
	 * Its health bar as the game last showed it, [ratio, scale], or null when the plugin has seen none since it spawned,
	 * or since a heal, which the bar has not shown yet.
	 */
	public int[] getHealth()
	{
		return health == null ? null : health.clone();
	}

	/** How many ticks ago its last attack animation started, or null when the plugin has seen none. */
	public Integer getSinceAttack()
	{
		return sinceAttack;
	}

	/**
	 * The attacks it has made, or null when the plugin does not know: it saw the NPC spawn and counted each one since, or
	 * for a Javelin Colossus it saw a special, which sets the count to a multiple of 5.
	 */
	public Integer getAttacks()
	{
		return attacks;
	}

	public NpcKind getKind()
	{
		return kind;
	}

	public GridTile getTile()
	{
		return tile;
	}

	/** The Manticore's LoS link orb code, or null for any other NPC. */
	public String getOrbs()
	{
		return orbs;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Objects;

/**
 * A tile of the arena in the LoS tool's terms, as Sol Survivor's state link holds it: x runs east and y south, each from
 * 0 to 33.
 */
public final class GridTile
{
	private final int x;
	private final int y;

	public GridTile(int x, int y)
	{
		this.x = x;
		this.y = y;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof GridTile))
		{
			return false;
		}
		GridTile t = (GridTile) o;
		return x == t.x && y == t.y;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(x, y);
	}

	@Override
	public String toString()
	{
		return "(" + x + "," + y + ")";
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.EnumSet;
import java.util.Set;

/**
 * The Colosseum's modifiers: the game's id for each (its bit in the taken-modifiers mask the selector script gets), the
 * varbit that holds its tier where it has tiers, and its key in the state link's `modifiers` (SimConfig's names). The ids
 * and varbits are the ones the Fortis Colosseum plugin reads (LlemonDuck, BSD 2-Clause). Bees! and Dynamic Duo are
 * exported as "bees" and "dynamicDuo" so that the link names every modifier taken; the site does not simulate them, and
 * its reader passes over names it does not know.
 */
public enum Modifier
{
	MANTIMAYHEM(0, 4588, "mantimayhem"),
	REENTRY(1, 9792, "reentry"),
	BEES(2, 9791, "bees"),
	VOLATILITY(3, 9799, "volatility"),
	BLASPHEMY(4, 9790, "blasphemy"),
	RELENTLESS(5, 9798, "relentless"),
	QUARTET(6, -1, "quartet"),
	TOTEMIC(7, -1, "totemic"),
	DOOM(8, 10681, "doom"),
	DYNAMIC_DUO(9, -1, "dynamicDuo"),
	SOLARFLARE(10, 9797, "solarflare"),
	MYOPIA(11, 9795, "myopia"),
	FRAILTY(12, 9796, "frailty"),
	RED_FLAG(13, -1, "redFlag");

	/** The level varbit of a modifier without tiers (written -1 above, where a constant cannot yet be named). */
	private static final int NO_TIERS = -1;

	private final int id;
	private final int levelVarbit;
	private final String key;

	Modifier(int id, int levelVarbit, String key)
	{
		this.id = id;
		this.levelVarbit = levelVarbit;
		this.key = key;
	}

	/** The game's id, which is also its bit in the taken-modifiers mask. */
	public int getId()
	{
		return id;
	}

	/** Whether it has tiers I to III, whose level a varbit holds. */
	public boolean hasTiers()
	{
		return levelVarbit != NO_TIERS;
	}

	/** The varbit that holds its tier, 0 while it is not taken; only for a modifier with tiers. */
	public int getLevelVarbit()
	{
		return levelVarbit;
	}

	/** Its key in the state link's `modifiers`. */
	public String getKey()
	{
		return key;
	}

	/** The modifier with a game id, or null for an id this plugin does not know. */
	public static Modifier forId(int id)
	{
		for (Modifier m : values())
		{
			if (m.id == id)
			{
				return m;
			}
		}
		return null;
	}

	/** The modifiers in a taken-modifiers mask. */
	public static Set<Modifier> forMask(int mask)
	{
		Set<Modifier> out = EnumSet.noneOf(Modifier.class);
		for (Modifier m : values())
		{
			if ((mask & (1 << m.id)) != 0)
			{
				out.add(m);
			}
		}
		return out;
	}
}

