	/**
	 * One tick of the wave: the player, the NPCs, the hitsplats that came with it, Solarflare's orbs, and the rest that
	 * came since the tick before.
	 */
	static final class Tick
	{
		final int t;
		final PlayerTick player;
		final List<Hit> playerHits;
		final List<NpcTick> npcs;
		/** The hitsplats on NPCs, by NPC index, in the order they came. */
		final Map<Integer, List<Hit>> npcHits;
		final List<GridTile> orbs;
		/**
		 * The animations NPCs started since the last tick, [index, animation id] each, in the order they came. Unlike the
		 * animation an NPC shows on a tick, these mark each start, an attack that repeats the one before included, which
		 * is what times the NPCs' attacks.
		 */
		final List<int[]> animations;
		/** The animations the player started since the last tick, in the order they came: each attack, a repeat included. */
		final List<Integer> playerAnimations;
		/** The item ids worn, on the wave's first tick and on each tick the gear changed; null on the others. */
		final int[] worn;
		/** The graphics the game put on the grid's tiles since the last tick, [x, y, graphic id] each, in the order they came. */
		final List<int[]> tileGraphics;
		/** The projectiles first seen since the last tick, in the order they were seen. */
		final List<Projectile> projectiles;
		/** The game's counters (ColosseumCounter) that changed since the last tick, every one on the wave's first tick. */
		final Map<ColosseumCounter, Integer> counters;

		/** A tick with no projectiles and no counters, as a test builds one. */
		Tick(int t, PlayerTick player, List<Hit> playerHits, List<NpcTick> npcs, Map<Integer, List<Hit>> npcHits, List<GridTile> orbs,
			List<int[]> animations, List<Integer> playerAnimations, int[] worn, List<int[]> tileGraphics)
		{
			this(t, player, playerHits, npcs, npcHits, orbs, animations, playerAnimations, worn, tileGraphics, Collections.<Projectile>emptyList(),
				Collections.<ColosseumCounter, Integer>emptyMap());
		}

		Tick(int t, PlayerTick player, List<Hit> playerHits, List<NpcTick> npcs, Map<Integer, List<Hit>> npcHits, List<GridTile> orbs,
			List<int[]> animations, List<Integer> playerAnimations, int[] worn, List<int[]> tileGraphics, List<Projectile> projectiles,
			Map<ColosseumCounter, Integer> counters)
		{
			this.t = t;
			this.player = player;
			this.playerHits = playerHits;
			this.npcs = npcs;
			this.npcHits = npcHits;
			this.orbs = orbs;
			this.animations = animations;
			this.playerAnimations = playerAnimations;
			this.worn = worn;
			this.tileGraphics = tileGraphics;
			this.projectiles = projectiles;
			this.counters = counters;
		}
	}

	/** The gear slots `worn` lists, in its order: those the state link names (Equipment), not the player's look. */
	public static final List<String> WORN_SLOTS = Collections.unmodifiableList(Arrays.asList(
		"head", "cape", "amulet", "weapon", "body", "shield", "legs", "gloves", "boots", "ring", "ammo"));

	private Integer wave;
	private int startTick;
	private Map<Modifier, Integer> modifiers = new EnumMap<>(Modifier.class);
	private boolean modifiersComplete;
	private String version = "";
	/** The state link's payload on the wave's first tick, as StatePayload wrote it, or null when it could not be taken. */
	private String startState;
	/**
	 * The same payload with the gear's levels left out (Equipment.withoutLevels), for the log the player shares
	 * (WaveLogWriter.toShare), or null when it could not be taken.
	 */
	private String shareState;
	/** The state link's payload on the tick the reinforcements came, or null before then. */
	private String reinforcementState;
	private final List<Tick> ticks = new ArrayList<>();
	private boolean cut;
	private End end;
	private boolean recording;
	/** The log's id, which tells it apart from the past ones, and the last id given. */
	private int id;
	private int lastId;
	/** The past waves' logs, newest first. */
	private final List<Past> past = new ArrayList<>();
	/** The gear worn on the last tick recorded, so that a tick lists it only when it changed. */
	private int[] lastWorn;
	/** The game's counters on the last tick recorded, so that a tick lists only those that changed; null before the first. */
	private int[] lastCounters;
	/** The game's glory counter on the first tick recorded that read it, null before then, and on the last. */
	private Integer firstGlory;
	private int lastGlory;

	/** The hitsplats since the last tick was recorded, which go in the next one. */
	private final List<Hit> pendingPlayerHits = new ArrayList<>();
	private final Map<Integer, List<Hit>> pendingNpcHits = new LinkedHashMap<>();
	/** The animations NPCs started since the last tick was recorded, which go in the next one. */
	private final List<int[]> pendingAnimations = new ArrayList<>();
	/** The animations the player started since the last tick was recorded. */
	private final List<Integer> pendingPlayerAnimations = new ArrayList<>();
	/** The graphics put on tiles since the last tick was recorded. */
	private final List<int[]> pendingTileGraphics = new ArrayList<>();
	/** The projectiles first seen since the last tick was recorded. */
	private final List<Projectile> pendingProjectiles = new ArrayList<>();

	/**
	 * A wave starts on game tick `gameTick`: the last wave's log goes among the past ones, and the log records this one.
	 * `startState` is the state link's payload on this tick (StatePayload.toJson), or null. The hitsplats already passed on
	 * this tick are kept for it.
	 */
	public void start(int wave, int gameTick, Map<Modifier, Integer> modifiers, boolean modifiersComplete, String version, String startState)
	{
		start(wave, gameTick, modifiers, modifiersComplete, version, startState, startState);
	}

	/**
	 * A wave starts, as start above, with `shareState` the state link's payload on this tick without the gear's levels, for
	 * the log the player shares, or null.
	 */
	public void start(int wave, int gameTick, Map<Modifier, Integer> modifiers, boolean modifiersComplete, String version, String startState,
		String shareState)
	{
		if (this.wave != null)
		{
			WaveLog done = snapshot();
			past.add(0, new Past(id, this.wave, ticks.size(), end, false, once(() -> WaveLogWriter.toJson(done)), this.startState, reinforcementState,
				getGlory()));
			while (past.size() > MAX_PAST)
			{
				past.remove(past.size() - 1);
			}
		}
		this.wave = wave;
		this.startTick = gameTick;
		this.modifiers = new EnumMap<>(Modifier.class);
		this.modifiers.putAll(modifiers);
		this.modifiersComplete = modifiersComplete;
		this.version = version;
		this.startState = startState;
		this.shareState = shareState;
		reinforcementState = null;
		ticks.clear();
		cut = false;
		end = null;
		recording = true;
		id = ++lastId;
		lastWorn = null;
		lastCounters = null;
		firstGlory = null;
		lastGlory = 0;
	}

	/** A hitsplat on the player, as it comes; it goes in the next tick recorded. */
	public void onPlayerHit(int amount, int type)
	{
		pendingPlayerHits.add(new Hit(amount, type));
	}

	/** A hitsplat on the NPC at `index`, as it comes; it goes in the next tick recorded. */
	public void onNpcHit(int index, int amount, int type)
	{
		pendingNpcHits.computeIfAbsent(index, i -> new ArrayList<>()).add(new Hit(amount, type));
	}

	/** An NPC started an animation, as it comes; it goes in the next tick recorded. */
	public void onNpcAnimation(int index, int animation)
	{
		pendingAnimations.add(new int[] {index, animation});
	}

	/** The player started an animation, as it comes; it goes in the next tick recorded. */
	public void onPlayerAnimation(int animation)
	{
		pendingPlayerAnimations.add(animation);
	}

	/**
	 * The game put a graphic on a tile, such as where a Javelin Colossus's special lands, as it comes; it goes in the next
	 * tick recorded. One off the grid, or with no tile, is left out.
	 */
	public void onTileGraphic(GridTile tile, int graphic)
	{
		if (tile != null && ArenaGeometry.onGrid(tile))
		{
			pendingTileGraphics.add(new int[] {tile.getX(), tile.getY(), graphic});
		}
	}

	/**
	 * A projectile the RuneLite layer saw for the first time, as it comes; it goes in the next tick recorded. One with
	 * neither an actor nor a tile on the grid at either end is left out.
	 */
	public void onProjectile(Projectile projectile)
	{
		if (projectile.isPlaced())
		{
			pendingProjectiles.add(projectile);
		}
	}

	/**
	 * Game tick `gameTick` of the wave: the player and every NPC the game shows. NPCs off the grid are left out, and the
	 * tiles of Solarflare's orbs are taken from the orb NPCs. The player's gear is kept for the tick only when it changed
	 * since the tick before. A tick already recorded, or one past MAX_TICKS, is passed over; either way the hitsplats since
	 * the last tick are used up.
	 */
	public void record(int gameTick, PlayerTick player, List<NpcTick> npcs)
	{
		record(gameTick, player, npcs, null);
	}

	/**
	 * Game tick `gameTick` of the wave, as record above, with `counters` the game's counters on it, one for each
	 * ColosseumCounter in its order, or null when they could not be read. The tick keeps those that changed since the tick
	 * before, and every one on the wave's first tick.
	 */
	public void record(int gameTick, PlayerTick player, List<NpcTick> npcs, int[] counters)
	{
		if (!recording)
		{
			discardPending();
			return;
		}
		int t = gameTick - startTick;
		if (!ticks.isEmpty() && ticks.get(ticks.size() - 1).t >= t)
		{
			discardPending();
			return;
		}
		if (ticks.size() >= MAX_TICKS)
		{
			cut = true;
			discardPending();
			return;
		}
		List<NpcTick> onGrid = new ArrayList<>();
		List<GridTile> orbs = new ArrayList<>();
		for (NpcTick n : npcs)
		{
			if (n.getTile() == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			onGrid.add(n);
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID)
			{
				orbs.add(n.getTile());
			}
		}
		Map<Integer, List<Hit>> npcHits = new LinkedHashMap<>();
		for (Map.Entry<Integer, List<Hit>> e : pendingNpcHits.entrySet())
		{
			npcHits.put(e.getKey(), Collections.unmodifiableList(new ArrayList<>(e.getValue())));
		}
		int[] worn = player == null ? null : player.getWorn();
		int[] changed = worn != null && !Arrays.equals(worn, lastWorn) ? worn : null;
		if (worn != null)
		{
			lastWorn = worn;
		}
		Map<ColosseumCounter, Integer> changedCounters = new EnumMap<>(ColosseumCounter.class);
		if (counters != null && counters.length == ColosseumCounter.values().length)
		{
			for (ColosseumCounter c : ColosseumCounter.values())
			{
				int value = counters[c.ordinal()];
				if (lastCounters == null || lastCounters[c.ordinal()] != value)
				{
					changedCounters.put(c, value);
				}
			}
			lastCounters = counters.clone();
			int glory = counters[ColosseumCounter.CURRENT_GLORY.ordinal()];
			if (firstGlory == null)
			{
				firstGlory = glory;
			}
			lastGlory = glory;
		}
		ticks.add(new Tick(t, player, Collections.unmodifiableList(new ArrayList<>(pendingPlayerHits)), Collections.unmodifiableList(onGrid),
			Collections.unmodifiableMap(npcHits), Collections.unmodifiableList(orbs), Collections.unmodifiableList(new ArrayList<>(pendingAnimations)),
			Collections.unmodifiableList(new ArrayList<>(pendingPlayerAnimations)), changed, Collections.unmodifiableList(new ArrayList<>(pendingTileGraphics)),
			Collections.unmodifiableList(new ArrayList<>(pendingProjectiles)), Collections.unmodifiableMap(changedCounters)));
		discardPending();
	}

	/**
	 * Forget the hitsplats and the rest since the last tick: the RuneLite layer calls this on each tick it does not
	 * record.
	 */
	public void discardPending()
	{
		pendingPlayerHits.clear();
		pendingNpcHits.clear();
		pendingAnimations.clear();
		pendingPlayerAnimations.clear();
		pendingTileGraphics.clear();
		pendingProjectiles.clear();
	}

	/** The wave ended: the log stops recording and is kept until the next wave starts. */
	public void finish(End how)
	{
		if (recording)
		{
			recording = false;
			end = how;
		}
		discardPending();
	}

	/** Forget the log and the past ones altogether: the plugin or its log was switched off. */
	public void clear()
	{
		wave = null;
		ticks.clear();
		cut = false;
		end = null;
		recording = false;
		modifiers = new EnumMap<>(Modifier.class);
		modifiersComplete = false;
		version = "";
		startState = null;
		shareState = null;
		reinforcementState = null;
		id = 0;
		lastWorn = null;
		lastCounters = null;
		firstGlory = null;
		lastGlory = 0;
		past.clear();
		discardPending();
	}

	/**
	 * The wave's reinforcements came on this tick: `state` is the state link's payload on it (StatePayload.toJson), which
	 * the panel opens on the site. Only the first is kept, while the wave records.
	 */
	public void reinforcementsCame(String state)
	{
		if (recording && reinforcementState == null)
		{
			reinforcementState = state;
		}
	}

	/** Whether the reinforcements' state was taken this wave. */
	public boolean hasReinforcementState()
	{
		return reinforcementState != null;
	}

	/** Whether a wave is being recorded. */
	public boolean isRecording()
	{
		return recording;
	}

	/** Whether there is a log to copy: a wave was started, while recording or after. */
	public boolean hasLog()
	{
		return wave != null;
	}

	/** The log's id, given when its wave started, or 0 when there is none. */
	public int getId()
	{
		return id;
	}

	/** The past waves' logs, newest first. */
	public List<Past> getPast()
	{
		return Collections.unmodifiableList(past);
	}

	/**
	 * The newest run's logs, oldest first, for RunLogWriter: the newest log, the wave under way or the last one, and going
	 * back from it each log whose wave is the one before the wave of the log after it. The run starts at wave 1, which has
	 * no wave before it, so that it never reaches back into the run before; or, when the plugin did not log the run from
	 * wave 1, such as when it started mid-run, at the oldest wave of the series it logged. A wave missing from the series
	 * or logged twice parts it there, and the run is the newer part. How a wave ended does not part a run: the next run
	 * starts at wave 1 again, which parts the two already. The past waves kept, MAX_PAST, are more than a run's 12 waves
	 * (wave 12 is Sol Heredit's), so that a run is always whole. Each log is as Copy wave log copies it: a past one as
	 * its JSON, and the newest as WaveLogWriter writes it now. Empty when there is no log.
	 */
	public List<Past> getRun()
	{
		List<List<Past>> runs = getRuns();
		return runs.isEmpty() ? Collections.<Past>emptyList() : runs.get(0);
	}

	/**
	 * Every run logged, newest first, each its logs oldest first: the newest is getRun's, and each run before it is
	 * parted from the next the same way, where a log's wave is not the one before the wave of the log after it. The
	 * wave under way or the last one comes as it is now (snapshot), its JSON written when it is asked for, and the waves
	 * restored from an earlier session after this session's. Empty when there is no log, past or present.
	 */
	public List<List<Past>> getRuns()
	{
		List<Past> newestFirst = new ArrayList<>();
		if (wave != null)
		{
			newestFirst.add(current());
		}
		newestFirst.addAll(past);
		List<List<Past>> runs = new ArrayList<>();
		List<Past> run = new ArrayList<>();
		for (Past p : newestFirst)
		{
			if (!run.isEmpty() && p.getWave() != run.get(0).getWave() - 1)
			{
				runs.add(Collections.unmodifiableList(run));
				run = new ArrayList<>();
			}
			run.add(0, p);
		}
		if (!run.isEmpty())
		{
			runs.add(Collections.unmodifiableList(run));
		}
		return Collections.unmodifiableList(runs);
	}

	/**
	 * The wave under way or the last one as a Past, as it is now (snapshot), its JSON written when it is asked for, on
	 * any thread: what getRuns lists first, and what the plugin saves as the wave ends (WaveStore). Null when there is no
	 * log.
	 */
	public Past current()
	{
		if (wave == null)
		{
			return null;
		}
		WaveLog now = snapshot();
		return new Past(id, wave, ticks.size(), end, recording, once(() -> WaveLogWriter.toJson(now)), startState, reinforcementState,
			getGlory());
	}

	/**
	 * Waves saved in an earlier session (WaveStore), newest first, go behind the past ones, each under a new id, so that
	 * Past waves lists them as it lists this session's: getRuns parts them into runs the same way. Those past MAX_PAST
	 * are let go.
	 */
	public void restore(List<Past> saved)
	{
		for (Past p : saved)
		{
			if (past.size() >= MAX_PAST)
			{
				break;
			}
			past.add(p.withId(++lastId));
		}
	}

	/**
	 * The glory the wave earned by the game's own counter, COLOSSEUM_CURRENT_GLORY: what it read on the last tick
	 * recorded less what it read on the first, which matched the site's sums by the game's rules on every wave finished
	 * in the user's shared runs of 25 and 26 October (the site's test/viewer/runGlory.test.ts). Only for a wave completed:
	 * a wave the player died in or left earns none, and one under way has not earned its yet. Null too when the counter
	 * could not be read.
	 */
	public Integer getGlory()
	{
		return end == End.COMPLETED && firstGlory != null ? lastGlory - firstGlory : null;
	}

	/**
	 * The log as it is now, which records nothing more: what WaveLogWriter writes of it, copied, so that its JSON can be
	 * written later, on any thread, while this log goes on. The ticks themselves never change once recorded, so only
	 * their list is copied.
	 */
	public WaveLog snapshot()
	{
		WaveLog copy = new WaveLog();
		copy.wave = wave;
		copy.startTick = startTick;
		copy.modifiers = new EnumMap<>(Modifier.class);
		copy.modifiers.putAll(modifiers);
		copy.modifiersComplete = modifiersComplete;
		copy.version = version;
		copy.startState = startState;
		copy.shareState = shareState;
		copy.reinforcementState = reinforcementState;
		copy.ticks.addAll(ticks);
		copy.cut = cut;
		copy.end = end;
		copy.id = id;
		copy.lastId = lastId;
		copy.firstGlory = firstGlory;
		copy.lastGlory = lastGlory;
		return copy;
	}

	/**
	 * `make`'s text, made the first time it is asked for and kept: a log's JSON, which may be asked for on the client
	 * thread or on OkHttp's, hence the lock. Once made, `make` is let go, and with it the snapshot it writes.
	 */
	static Supplier<String> once(Supplier<String> make)
	{
		return new Supplier<String>()
		{
			private Supplier<String> maker = make;
			private String text;

			@Override
			public synchronized String get()
			{
				if (text == null)
				{
					text = maker.get();
					maker = null;
				}
				return text;
			}
		};
	}

	/** The wave logged, or null when there is none. */
	public Integer getWave()
	{
		return wave;
	}

	/** How many ticks the log holds. */
	public int size()
	{
		return ticks.size();
	}

	/** Whether ticks were left out because the log was full. */
	public boolean isCut()
	{
		return cut;
	}

	/** How the wave ended, or null while it is under way or when the log was never finished. */
	public End getEnd()
	{
		return end;
	}

	Map<Modifier, Integer> getModifiers()
	{
		return Collections.unmodifiableMap(modifiers);
	}

	boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	String getVersion()
	{
		return version;
	}

	String getStartState()
	{
		return startState;
	}

	String getShareState()
	{
		return shareState;
	}

	/** The state link's payload on the tick the reinforcements came, or null before then. */
	public String getReinforcementState()
	{
		return reinforcementState;
	}

	List<Tick> getTicks()
	{
		return Collections.unmodifiableList(ticks);
	}

	/**
	 * A prayer's name in the log, from the name of RuneLite's Prayer constant: the three protection prayers are "magic",
	 * "ranged" and "melee", as the site names them, and every other prayer is its constant's name in lower case, such as
	 * "piety" or "rp_ancient_strength".
	 */
	public static String prayerName(String prayerConstant)
	{
		switch (prayerConstant)
		{
			case "PROTECT_FROM_MAGIC":
				return "magic";
			case "PROTECT_FROM_MISSILES":
				return "ranged";
			case "PROTECT_FROM_MELEE":
				return "melee";
			default:
				return prayerConstant.toLowerCase(Locale.ROOT);
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The wave log's JSON, for the site's log checker (src/viewer/waveLogCheck.ts). Like StatePayload it is written by
 * hand, ASCII only and in a fixed order, so that a log always gives the same text and the tests can compare it whole;
 * each tick is on a line of its own, so that a log reads and diffs a tick at a time.
 *
 * <pre>
 * {"v":1,"kind":"solSurvivorWaveLog","plugin":"0.2.0","wave":4,
 *  "modifiers":{"reentry":2,"quartet":"random"},"modifiersComplete":true,
 *  "maxTicks":1500,"cut":false,"end":"completed","start":{"v":1,"setup":{...}},"ticks":[
 * {"t":0,"player":[7,15,99,77,["magic","piety"],-1,null],"hits":[],
 *  "npcs":[[11,12811,13,20,-1,-1,-1,"player",[]],[12,12818,16,24,7590,30,30,"player",[[0,12]]]],"orbs":[],
 *  "worn":[26382,21295,-1,20997,26384,-1,26386,-1,-1,-1,-1]},
 * {"t":1,...,"anims":[[11,10859]],"playerAnims":[426],"spots":[[12,2681]],"projectiles":[[2678,12,"player",0,51]],
 *  "counters":{"waveDamageTaken":13}},
 * ...
 * ]}
 * </pre>
 *
 * <ul>
 * <li>`v`: the log's version, 1; `kind`: always "solSurvivorWaveLog", which tells it apart from a state link's payload;
 * `plugin`: the plugin's version.</li>
 * <li>`wave`: the wave, 1 to 11, or 12 for Sol Heredit's.</li>
 * <li>`modifiers`: the modifiers taken at the wave's start, written as the state link writes them (its tier, true or
 * "random"); `modifiersComplete`: whether Quartet, Red Flag and Totemic are known (see ArenaState).</li>
 * <li>`maxTicks`: the most ticks a log holds; `cut`: whether the wave ran past it and the rest was left out.</li>
 * <li>`end`: "completed" when the game said the wave was completed, "left" when the player left the arena (died, ran or
 * logged out), null while the wave is under way, or when the next wave started before its end was seen.</li>
 * <li>`start`: the state link's payload on the wave's first tick (StatePayload, the site's src/link/statePayload.ts),
 * with the gear and stats when "Include gear and stats" is on, so that the site can plan the wave from where it began
 * and put the plan beside what the player did; null when it could not be taken.</li>
 * <li>`ticks`: one object a game tick, from the wave's first tick on, but for the repeats a tick's `repeats` stands for:
 * <ul>
 * <li>`t`: the tick within the wave, 0 on the tick of the game's "Wave: N" message;</li>
 * <li>`player`: [x, y, hitpoints, prayer points, [prayers on], animation id, target], with x and y the grid tile (null
 * off the grid), the prayers as WaveLog.prayerName names them, -1 for no animation, and the target an NPC's index,
 * "player" or null;</li>
 * <li>`hits`: the hitsplats on the player that came with this tick, [amount, hitsplat type id] each;</li>
 * <li>`npcs`: every NPC on the grid, by its raw id: [index, NPC id, x, y, animation id, health ratio, health scale,
 * target, [hitsplats]], with x and y its south-west tile, -1 for no animation and for an unknown health ratio or scale,
 * the target as the player's, and its hitsplats this tick as the player's;</li>
 * <li>`orbs`: the tiles of Solarflare's orbs (NPC 12826), [x, y] each, which are in `npcs` too;</li>
 * <li>`strayHits`, only when there are any: hitsplats on an NPC that is not in `npcs` this tick, [index, amount, type]
 * each;</li>
 * <li>`anims`, only when there are any: the animations NPCs started since the tick before, [index, animation id] each,
 * in the order they came. Each start is there, an attack that repeats the one before included, where the animation in
 * `npcs` only shows what an NPC is doing on the tick. An NPC whose animation stops is there too, with -1.</li>
 * <li>`playerAnims`, only when there are any: the animations the player started since the tick before, as `anims` has
 * the NPCs', so that each of the player's attacks is there even when the weapon's animation runs on unbroken.</li>
 * <li>`spots`, only when there are any: the graphics the NPCs in `npcs` show on the tick, [index, graphic id] each, such
 * as a Manticore's orbs as it charges them, unfiltered.</li>
 * <li>`worn`, on the wave's first tick and on each tick the player's gear changed, when "Include gear and stats" is on:
 * the item id in each slot of WaveLog.WORN_SLOTS, in its order, -1 for an empty one.</li>
 * <li>`tileGraphics`, only when there are any: the graphics the game put on the grid's tiles since the tick before,
 * [x, y, graphic id] each, in the order they came, unfiltered, such as where a Javelin Colossus's special lands.</li>
 * <li>`projectiles`, only when there are any (from 0.8.0): the projectiles first seen since the tick before, [graphic id,
 * from, to, start, end] each, in the order they were seen, unfiltered. From and to are each an NPC's index, "player",
 * or, at an end with no actor, such as a Javelin Colossus's special aimed at a tile, that tile as [x, y], null off the
 * grid. Start and end are the client cycles (20 ms, 30 to a tick) from this tick to when it sets off and when it lands,
 * below 0 for one that set off before this tick, as one first seen a tick late may have; end less start is its flight.
 * The Venator bow's bounces are each one from the NPC it bounces off to the next.</li>
 * <li>`counters`, on the wave's first tick and on each tick one changed (from 0.8.0): the game's own counters for the
 * wave and the run (ColosseumCounter), by key, such as Doom's stacks ("doomStacks") and the game's current glory
 * ("currentGlory"); those that did not change since the tick before are left out.</li>
 * <li>`repeats`, only when there are any (from 0.8.4): how many ticks after this one were the same as it in all but their
 * `t`, which are left out. A reader puts each back as a copy of this tick, `t` aside. A wait where nothing changes, as
 * while the player plans the next move on the site, is then one line rather than hundreds.</li>
 * </ul>
 * </li>
 * </ul>
 * The hitsplats of a tick are those the game showed since the tick before, which RuneLite passes on between ticks.
 */
public final class WaveLogWriter
{
	/** The log's version. */
	public static final int VERSION = 1;

	/** The log's `kind`. */
	public static final String KIND = "solSurvivorWaveLog";

	private WaveLogWriter()
	{
	}

	/** The log's JSON; an empty log, with no wave, has a null wave and no ticks. */
	public static String toJson(WaveLog log)
	{
		return toJson(log, log.getStartState(), false);
	}

	/**
	 * The log as the player shares it with "Share wave logs" (WaveShare): the same JSON, but with its `start` written
	 * without the gear's levels and prayer unlocks (Equipment.withoutLevels), which the site refuses in a shared log, and
	 * its ticks' counters without those that are not shared (ColosseumCounter.isShared).
	 */
	public static String toShare(WaveLog log)
	{
		return toJson(log, log.getShareState(), true);
	}

	private static String toJson(WaveLog log, String start, boolean shared)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"kind\":");
		StatePayload.string(b, KIND);
		b.append(",\"plugin\":");
		StatePayload.string(b, log.getVersion());
		b.append(",\"wave\":").append(log.getWave());
		b.append(",\"modifiers\":{");
		boolean first = true;
		for (Map.Entry<Modifier, Integer> e : log.getModifiers().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			StatePayload.string(b, e.getKey().getKey());
			b.append(':').append(StatePayload.valueOf(e.getKey(), e.getValue()));
		}
		b.append("},\"modifiersComplete\":").append(log.isModifiersComplete());
		b.append(",\"maxTicks\":").append(WaveLog.MAX_TICKS);
		b.append(",\"cut\":").append(log.isCut());
		b.append(",\"end\":");
		if (log.getEnd() == null)
		{
			b.append("null");
		}
		else
		{
			StatePayload.string(b, log.getEnd().getKey());
		}
		b.append(",\"start\":").append(start == null ? "null" : start);
		b.append(",\"ticks\":[");
		// A tick the same as the one before it, its t aside, is left out, and the tick before says how many repeat it.
		List<WaveLog.Tick> ticks = log.getTicks();
		List<String> bodies = new ArrayList<>(ticks.size());
		for (WaveLog.Tick tick : ticks)
		{
			StringBuilder body = new StringBuilder();
			tick(body, tick, shared);
			bodies.add(body.toString());
		}
		for (int i = 0; i < ticks.size(); )
		{
			int repeats = 0;
			while (i + repeats + 1 < ticks.size() && ticks.get(i + repeats + 1).t == ticks.get(i).t + repeats + 1
				&& bodies.get(i + repeats + 1).equals(bodies.get(i)))
			{
				repeats++;
			}
			b.append(i == 0 ? "\n" : ",\n").append("{\"t\":").append(ticks.get(i).t).append(bodies.get(i));
			if (repeats > 0)
			{
				b.append(",\"repeats\":").append(repeats);
			}
			b.append('}');
			i += repeats + 1;
		}
		b.append(ticks.isEmpty() ? "]}" : "\n]}");
		return b.toString();
	}

	/** A tick's JSON after its `t`, up to its closing brace: the same text for two ticks that showed the same. */
	private static void tick(StringBuilder b, WaveLog.Tick tick, boolean shared)
	{
		b.append(",\"player\":");
		WaveLog.PlayerTick p = tick.player;
		if (p == null)
		{
			b.append("null");
		}
		else
		{
			b.append('[');
			tile(b, p.getTile());
			b.append(',').append(p.getHitpoints()).append(',').append(p.getPrayerPoints()).append(",[");
			boolean first = true;
			for (String prayer : p.getPrayers())
			{
				if (!first)
				{
					b.append(',');
				}
				first = false;
				StatePayload.string(b, prayer);
			}
			b.append("],").append(p.getAnimation()).append(',');
			target(b, p.getTarget());
			b.append(']');
		}
		b.append(",\"hits\":");
		hits(b, tick.playerHits);

		b.append(",\"npcs\":[");
		boolean first = true;
		for (WaveLog.NpcTick n : tick.npcs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(n.getIndex()).append(',').append(n.getNpcId()).append(',');
			tile(b, n.getTile());
			b.append(',').append(n.getAnimation()).append(',').append(n.getHealthRatio()).append(',').append(n.getHealthScale()).append(',');
			target(b, n.getTarget());
			b.append(',');
			hits(b, tick.npcHits.getOrDefault(n.getIndex(), Collections.emptyList()));
			b.append(']');
		}
		b.append("],\"orbs\":[");
		first = true;
		for (GridTile t : tick.orbs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(t.getX()).append(',').append(t.getY()).append(']');
		}
		b.append(']');

		// Hitsplats on an NPC the tick does not list, such as one that despawned before the tick's snapshot, are kept.
		StringBuilder stray = new StringBuilder();
		for (Map.Entry<Integer, List<WaveLog.Hit>> e : tick.npcHits.entrySet())
		{
			if (listed(tick.npcs, e.getKey()))
			{
				continue;
			}
			for (WaveLog.Hit h : e.getValue())
			{
				stray.append(stray.length() == 0 ? "" : ",").append('[').append(e.getKey()).append(',').append(h.getAmount()).append(',')
					.append(h.getType()).append(']');
			}
		}
		if (stray.length() > 0)
		{
			b.append(",\"strayHits\":[").append(stray).append(']');
		}
		if (!tick.animations.isEmpty())
		{
			b.append(",\"anims\":[");
			for (int i = 0; i < tick.animations.size(); i++)
			{
				int[] a = tick.animations.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(a[0]).append(',').append(a[1]).append(']');
			}
			b.append(']');
		}
		if (!tick.playerAnimations.isEmpty())
		{
			b.append(",\"playerAnims\":[");
			for (int i = 0; i < tick.playerAnimations.size(); i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.playerAnimations.get(i));
			}
			b.append(']');
		}
		StringBuilder spots = new StringBuilder();
		for (WaveLog.NpcTick n : tick.npcs)
		{
			for (int id : n.getSpotAnims())
			{
				spots.append(spots.length() == 0 ? "" : ",").append('[').append(n.getIndex()).append(',').append(id).append(']');
			}
		}
		if (spots.length() > 0)
		{
			b.append(",\"spots\":[").append(spots).append(']');
		}
		if (tick.worn != null)
		{
			b.append(",\"worn\":[");
			for (int i = 0; i < tick.worn.length; i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.worn[i]);
			}
			b.append(']');
		}
		if (!tick.tileGraphics.isEmpty())
		{
			b.append(",\"tileGraphics\":[");
			for (int i = 0; i < tick.tileGraphics.size(); i++)
			{
				int[] g = tick.tileGraphics.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(g[0]).append(',').append(g[1]).append(',').append(g[2]).append(']');
			}
			b.append(']');
		}
		if (!tick.projectiles.isEmpty())
		{
			b.append(",\"projectiles\":[");
			for (int i = 0; i < tick.projectiles.size(); i++)
			{
				WaveLog.Projectile shot = tick.projectiles.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(shot.getId()).append(',');
				end(b, shot.getFrom(), shot.getFromTile());
				b.append(',');
				end(b, shot.getTo(), shot.getToTile());
				b.append(',').append(shot.getStart()).append(',').append(shot.getEnd()).append(']');
			}
			b.append(']');
		}
		boolean firstCounter = true;
		for (Map.Entry<ColosseumCounter, Integer> e : tick.counters.entrySet())
		{
			if (shared && !e.getKey().isShared())
			{
				continue;
			}
			b.append(firstCounter ? ",\"counters\":{" : ",");
			firstCounter = false;
			StatePayload.string(b, e.getKey().getKey());
			b.append(':').append(e.getValue());
		}
		if (!firstCounter)
		{
			b.append('}');
		}
	}

	private static boolean listed(List<WaveLog.NpcTick> npcs, int index)
	{
		for (WaveLog.NpcTick n : npcs)
		{
			if (n.getIndex() == index)
			{
				return true;
			}
		}
		return false;
	}

	/** A tile as two numbers, x and y, or two nulls for none. */
	private static void tile(StringBuilder b, GridTile t)
	{
		if (t == null)
		{
			b.append("null,null");
		}
		else
		{
			b.append(t.getX()).append(',').append(t.getY());
		}
	}

	/** A projectile's end: its actor as a target is written, or with none the tile as [x, y], null off the grid. */
	private static void end(StringBuilder b, int actor, GridTile tile)
	{
		if (actor != WaveLog.TARGET_NONE)
		{
			target(b, actor);
		}
		else if (tile == null || !ArenaGeometry.onGrid(tile))
		{
			b.append("null");
		}
		else
		{
			b.append('[').append(tile.getX()).append(',').append(tile.getY()).append(']');
		}
	}

	private static void target(StringBuilder b, int target)
	{
		if (target == WaveLog.TARGET_PLAYER)
		{
			b.append("\"player\"");
		}
		else if (target < 0)
		{
			b.append("null");
		}
		else
		{
			b.append(target);
		}
	}

	private static void hits(StringBuilder b, List<WaveLog.Hit> hits)
	{
		b.append('[');
		boolean first = true;
		for (WaveLog.Hit h : hits)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(h.getAmount()).append(',').append(h.getType()).append(']');
		}
		b.append(']');
	}
}

package nl.dexanddice.solsurvivor.core;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Random;
import java.util.zip.GZIPOutputStream;

/**
 * The wave logs the player shares with "Share wave logs", off by default: each wave's log, as WaveLogWriter.toShare
 * writes it, gzipped and sent to the site's /api/wave-logs (its src/edge/waveLogs.ts) once, as the wave ends, so that the
 * planner can be checked against real games, and from 0.8.3 so that its Learned ranking is trained on how waves start
 * (its docs/wave-log-sharing.md). The site keeps it 90 days and shows it to nobody.
 *
 * A log is sent under a random id for its run, made when wave 1 starts, or a wave that does not follow the last one, and
 * forgotten when the player leaves the arena, so that the site can join a run's waves and drop one sent twice without
 * any id that ties one run of the player's to another. The RuneLite layer sends the request; this class only decides
 * the run, which log goes, and the body. It holds no RuneLite import, as the rest of the core.
 */
public final class WaveShare
{
	/** The header that carries the run's id, as the site reads it (RUN_HEADER). */
	public static final String RUN_HEADER = "x-sol-survivor-run";

	/** The body's type: the log's JSON, gzipped (SHARED_LOG_TYPE). */
	public static final String TYPE = "application/gzip";

	private final Random random;
	/** The run's id, or null when no run is under way. */
	private String run;
	/** The last wave seen to start in this run. */
	private int lastWave;
	/** The id of the last log handed out to share (WaveLog.getId), so that each goes once. */
	private int sharedId;

	public WaveShare()
	{
		this(new SecureRandom());
	}

	/** With the random numbers given, for the tests. */
	WaveShare(Random random)
	{
		this.random = random;
	}

	/** The site's endpoint for shared logs. */
	public static String endpoint(String site)
	{
		return ReplayLink.origin(site) + "/api/wave-logs";
	}

	/** A wave starts: a new run's id when it is wave 1 or does not follow the last wave seen, else the run's own. */
	public String onWaveStart(int wave)
	{
		if (run == null || wave == 1 || wave != lastWave + 1)
		{
			byte[] bytes = new byte[16];
			random.nextBytes(bytes);
			StringBuilder id = new StringBuilder(32);
			for (byte b : bytes)
			{
				id.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
			}
			run = id.toString();
		}
		lastWave = wave;
		return run;
	}

	/** The player left the arena, or the plugin stopped: the run's id is forgotten. */
	public void onLeave()
	{
		run = null;
		lastWave = 0;
	}

	/** The run's id, or null when no run is under way. */
	public String getRun()
	{
		return run;
	}

	/**
	 * Whether the log `logId` is still to be shared: true once for each log, and never for 0, no log. A log's turn comes
	 * as its wave ends, whether or not the setting is on, so that a wave played with sharing off is never sent later.
	 */
	public boolean claim(int logId)
	{
		if (logId == 0 || logId == sharedId)
		{
			return false;
		}
		sharedId = logId;
		return true;
	}

	/** The text gzipped, as the body the site takes. */
	public static byte[] gzip(String json)
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (GZIPOutputStream zip = new GZIPOutputStream(out))
		{
			zip.write(json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException ex)
		{
			// A stream in memory does not fail.
			throw new UncheckedIOException(ex);
		}
		return out.toByteArray();
	}
}

package nl.dexanddice.solsurvivor.core;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.Supplier;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

/**
 * A finished wave's log as "Keep runs between sessions" saves it, so that Past waves still holds it after RuneLite
 * closes: one gzipped file a wave, in the plugin's own folder of RuneLite's (Plugin.getPluginDirectory), each account's
 * apart. A file holds what WaveLog.Past does: the wave, its ticks, how it ended and the glory it earned, the state links'
 * payloads on its first tick and on the tick its reinforcements came, and its log as WaveLogWriter wrote it. The
 * RuneLite layer reads and writes the files, never on the client thread, as RuneLite's plugin guide asks; this class
 * only turns a wave into bytes and back, and names and sorts the files. It holds no RuneLite import, as the rest of the
 * core.
 *
 * The bytes are the plugin's own and nothing else reads them: a magic number and a version, then the fields in order,
 * each text its UTF-8 length and bytes, or -1 for none. A file of another version, or one cut short, is not read.
 */
public final class WaveStore
{
	/** How a saved wave's file name ends. */
	public static final String SUFFIX = ".wave.gz";

	/** The most waves kept on disk for an account: as many as WaveLog keeps, the wave under way with the past ones. */
	public static final int MAX_SAVED = WaveLog.MAX_PAST + 1;

	/** "SSWV": a file this class wrote. */
	private static final int MAGIC = 0x53535756;
	private static final int VERSION = 1;
	/** The most a text in a file may be: far past a wave's log, so that a damaged length cannot fill the memory. */
	private static final int MAX_TEXT_BYTES = 64 * 1024 * 1024;

	private WaveStore()
	{
	}

	/**
	 * The file name of a wave saved at `savedAt`, milliseconds since 1970: the time first, padded, so that the names sort
	 * as the waves were saved, then the wave, for a person looking in the folder.
	 */
	public static String fileName(long savedAt, int wave)
	{
		return String.format(Locale.ROOT, "%013d-wave%02d%s", savedAt, wave, SUFFIX);
	}

	/** The saved waves among the file names `names`, newest first; any other file in the folder is passed over. */
	public static List<String> newestFirst(Collection<String> names)
	{
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			if (name.endsWith(SUFFIX))
			{
				out.add(name);
			}
		}
		out.sort(Collections.reverseOrder());
		return out;
	}

	/** The saved waves among `names` past the newest `keep`, which the RuneLite layer deletes. */
	public static List<String> beyond(Collection<String> names, int keep)
	{
		List<String> sorted = newestFirst(names);
		return sorted.size() <= keep ? Collections.<String>emptyList() : new ArrayList<>(sorted.subList(keep, sorted.size()));
	}

	/** Writes `wave` to `out`, gzipped; its JSON is written here if it was not yet, so not on the client thread. */
	public static void write(WaveLog.Past wave, OutputStream out) throws IOException
	{
		GZIPOutputStream zip = new GZIPOutputStream(out);
		DataOutputStream data = new DataOutputStream(zip);
		data.writeInt(MAGIC);
		data.writeInt(VERSION);
		data.writeInt(wave.getWave());
		data.writeInt(wave.size());
		data.writeByte(wave.getEnd() == null ? 0 : wave.getEnd() == WaveLog.End.COMPLETED ? 1 : 2);
		data.writeBoolean(wave.getGlory() != null);
		data.writeInt(wave.getGlory() == null ? 0 : wave.getGlory());
		text(data, wave.getStartState());
		text(data, wave.getReinforcementState());
		text(data, wave.getJson());
		data.flush();
		zip.finish();
	}

	/**
	 * The wave `in` holds, as write wrote it, finished and under id 0 until WaveLog.restore gives it one; an IOException
	 * when it is not a saved wave of this version, or is cut short.
	 */
	public static WaveLog.Past read(InputStream in) throws IOException
	{
		DataInputStream data = new DataInputStream(new GZIPInputStream(in));
		if (data.readInt() != MAGIC || data.readInt() != VERSION)
		{
			throw new IOException("Not a saved wave of this version");
		}
		int wave = data.readInt();
		int size = data.readInt();
		int endCode = data.readByte();
		if (endCode < 0 || endCode > 2)
		{
			throw new IOException("A saved wave with an unknown end: " + endCode);
		}
		WaveLog.End end = endCode == 0 ? null : endCode == 1 ? WaveLog.End.COMPLETED : WaveLog.End.LEFT;
		boolean hasGlory = data.readBoolean();
		int glory = data.readInt();
		String startState = text(data);
		String reinforcementState = text(data);
		String json = text(data);
		if (json == null)
		{
			throw new IOException("A saved wave without its log");
		}
		Supplier<String> log = () -> json;
		return new WaveLog.Past(0, wave, size, end, false, log, startState, reinforcementState, hasGlory ? glory : null);
	}

	private static void text(DataOutputStream data, String text) throws IOException
	{
		if (text == null)
		{
			data.writeInt(-1);
			return;
		}
		byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
		data.writeInt(bytes.length);
		data.write(bytes);
	}

	private static String text(DataInputStream data) throws IOException
	{
		int length = data.readInt();
		if (length == -1)
		{
			return null;
		}
		if (length < 0 || length > MAX_TEXT_BYTES)
		{
			throw new IOException("A saved wave with a text of " + length + " bytes");
		}
		byte[] bytes = new byte[length];
		data.readFully(bytes);
		return new String(bytes, StandardCharsets.UTF_8);
	}
}

package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.zip.GZIPInputStream;
import nl.dexanddice.solsurvivor.core.RunUpload;
import okhttp3.MediaType;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReplayUploadTest
{
	private static final String SITE = "https://sol.example/";
	/** As RuneLite injects it. */
	private static final Gson GSON = new Gson();
	private static final String ID = "0123456789abcdef0123456789abcdef";

	private Response response(int status, String text)
	{
		return new Response.Builder().request(new Request.Builder().url(SITE).build()).protocol(Protocol.HTTP_1_1)
			.code(status).message("test").body(ResponseBody.create(MediaType.parse("application/json"), text)).build();
	}

	@Test
	public void selectedRunGoesInThePostBodyAndOnlyAValidatedIdOpens()
		throws Exception
	{
		// The run's JSON is written, and gzipped, only when OkHttp asks for the body, and once.
		String json = "{\"kind\":\"solSurvivorRun\"}";
		AtomicInteger written = new AtomicInteger();
		Request request = ReplayUpload.request(SITE, () ->
		{
			written.incrementAndGet();
			return json;
		});
		assertEquals(0, written.get());
		assertEquals("POST", request.method());
		assertEquals("https://sol.example/api/replays", request.url().toString());
		assertEquals("application/gzip", request.body().contentType().toString());
		Buffer sent = new Buffer();
		long length = request.body().contentLength();
		request.body().writeTo(sent);
		assertEquals(length, sent.size());
		assertEquals(1, written.get());
		try (GZIPInputStream in = new GZIPInputStream(new ByteArrayInputStream(sent.readByteArray())))
		{
			assertEquals(json, new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
		try (Response res = response(201, "{\"id\":\"" + ID + "\",\"url\":\"https://evil.example\"}"))
		{
			assertEquals(SITE + "#replay=" + ID, ReplayUpload.browserUrl(GSON, SITE, res));
		}
	}

	@Test
	public void failuresAndMalformedResponsesCannotOpenAnArbitraryUrl()
	{
		for (int status : new int[]{400, 413, 429, 503})
		{
			try (Response res = response(status, "{}"))
			{
				assertThrows(IOException.class, () -> ReplayUpload.browserUrl(GSON, SITE, res));
			}
		}
		for (String body : new String[]{"{}", "not json", "{\"id\":\"https://evil.example\"}", "x".repeat(4097)})
		{
			try (Response res = response(201, body))
			{
				assertThrows(IOException.class, () -> ReplayUpload.browserUrl(GSON, SITE, res));
			}
		}
		// A run too large fails the call as its body is made, with the message the player is shown.
		Request large = ReplayUpload.request(SITE, () -> "x".repeat(RunUpload.MAX_JSON_BYTES + 1));
		IOException refused = assertThrows(IOException.class, () -> large.body().contentLength());
		assertTrue(refused instanceof RunUpload.TooLarge);
	}
}

