import org.junit.Test;

/**
 * The run log, which "Copy whole run" copies: which of the waves logged make the newest run (WaveLog.getRun), and its
 * JSON (RunLogWriter), compared whole with src/test/resources/fixtures/run-log.json. The waves are started and recorded
 * as the RuneLite layer does it, with the plugin's version given as "test"; the NPC, animation and hitsplat type ids are
 * made up, as in WaveLogTest.
 */
public class RunLogTest
{
	/** The state link's payload on wave 1's first tick, as the RuneLite layer passes it on: here a short made-up one. */
	private static final String START_STATE = "{\"v\":1,\"setup\":{\"npcs\":[[13,20,\"2\"]],\"player\":[7,15],\"waveStart\":true,\"wave\":1}}";

	private WaveLog log;

	@Before
	public void setUp()
	{
		log = new WaveLog();
	}

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = RunLogTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	private static WaveLog.PlayerTick player(int x, int y, int hp)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), hp, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE);
	}

	private static WaveLog.NpcTick shaman(int index, int x, int y, int animation)
	{
		return new WaveLog.NpcTick(index, NpcKind.SHAMAN_ID, new GridTile(x, y), animation, -1, -1, WaveLog.TARGET_PLAYER);
	}

	/** Wave `wave` starts on game tick `gameTick` with no modifiers, and `ticks` ticks of it are recorded. */
	private void wave(int wave, int gameTick, int ticks)
	{
		log.start(wave, gameTick, Collections.emptyMap(), true, "test", null);
		for (int t = 0; t < ticks; t++)
		{
			log.record(gameTick + t, player(7, 15, 99), Collections.emptyList());
		}
	}

	/** The waves of the newest run, in the order the run gives them. */
	private List<Integer> runWaves()
	{
		List<Integer> out = new ArrayList<>();
		for (WaveLog.Past p : log.getRun())
		{
			out.add(p.getWave());
		}
		return out;
	}

	@Test
	public void aRunLog() throws Exception
	{
		// An earlier run, which the player left in wave 2.
		wave(1, 100, 2);
		log.finish(WaveLog.End.COMPLETED);
		wave(2, 200, 1);
		log.finish(WaveLog.End.LEFT);

		// The newest run: wave 1, completed; wave 2, whose end the plugin missed, with Reentry I taken; and wave 3 under way.
		Map<Modifier, Integer> reentry = new EnumMap<>(Modifier.class);
		reentry.put(Modifier.REENTRY, 1);
		log.start(1, 1000, Collections.emptyMap(), true, "test", START_STATE);
		log.record(1000, player(7, 15, 99), Collections.singletonList(shaman(11, 13, 20, -1)));
		log.onNpcHit(11, 14, 12);
		log.onNpcAnimation(11, 10859);
		log.record(1001, player(7, 14, 99), Collections.singletonList(shaman(11, 13, 19, 10859)));
		log.finish(WaveLog.End.COMPLETED);
		log.start(2, 1100, reentry, true, "test", null);
		log.record(1100, player(7, 15, 99), Arrays.asList(shaman(14, 13, 20, -1), shaman(15, 15, 20, -1)));
		log.start(3, 1200, reentry, true, "test", null);
		log.onPlayerHit(9, 16);
		log.record(1200, player(7, 15, 90), Collections.singletonList(shaman(16, 13, 20, -1)));

		assertEquals(Arrays.asList(1, 2, 3), runWaves());
		assertEquals(fixture("run-log.json"), RunLogWriter.toJson(log.getRun(), "test"));
	}

	@Test
	public void eachWaveIsAsCopyWaveLogCopiesIt()
	{
		wave(4, 100, 2);
		log.finish(WaveLog.End.COMPLETED);
		wave(5, 200, 3);
		log.finish(WaveLog.End.COMPLETED);
		wave(6, 300, 1);

		// The past waves as they were kept, and the wave under way as WaveLogWriter writes it now.
		String wave4 = log.getPast().get(1).getJson();
		String wave5 = log.getPast().get(0).getJson();
		String wave6 = WaveLogWriter.toJson(log);
		List<WaveLog.Past> run = log.getRun();
		assertEquals(Arrays.asList(wave4, wave5, wave6), Arrays.asList(run.get(0).getJson(), run.get(1).getJson(), run.get(2).getJson()));
		assertEquals(Arrays.asList(2, 3, 1), Arrays.asList(run.get(0).size(), run.get(1).size(), run.get(2).size()));
		assertEquals(log.getId(), run.get(2).getId());
		assertEquals("{\"v\":1,\"kind\":\"solSurvivorRun\",\"plugin\":\"test\",\"waves\":[\n" + wave4 + ",\n" + wave5 + ",\n" + wave6 + "\n]}",
			RunLogWriter.toJson(run, "test"));

		// The newest is written when the run is asked for, so that it holds the ticks recorded since.
		log.record(301, player(7, 14, 99), Collections.emptyList());
		assertEquals(2, log.getRun().get(2).size());
		assertEquals(WaveLogWriter.toJson(log), log.getRun().get(2).getJson());
	}

	@Test
	public void theRunStartsAtWave1AndNeverReachesIntoTheRunBefore()
	{
		wave(1, 100, 1);
		wave(2, 200, 1);
		wave(3, 300, 1);
		log.finish(WaveLog.End.LEFT);
		wave(1, 1000, 1);
		assertEquals(Collections.singletonList(1), runWaves());
		wave(2, 1100, 1);
		assertEquals(Arrays.asList(1, 2), runWaves());
	}

	@Test
	public void aRunThePluginJoinedLateStartsAtTheFirstWaveItLogged()
	{
		wave(4, 100, 1);
		wave(5, 200, 1);
		wave(6, 300, 1);
		log.finish(WaveLog.End.COMPLETED);
		assertEquals(Arrays.asList(4, 5, 6), runWaves());
	}

	@Test
	public void aWaveMissingOrLoggedTwicePartsTheRun()
	{
		// Wave 4 was not logged: the run is the newer part.
		wave(2, 100, 1);
		wave(3, 200, 1);
		wave(5, 300, 1);
		wave(6, 400, 1);
		assertEquals(Arrays.asList(5, 6), runWaves());

		log.clear();
		wave(3, 100, 1);
		wave(4, 200, 1);
		wave(4, 300, 1);
		assertEquals(Collections.singletonList(4), runWaves());
	}

	@Test
	public void howAWaveEndedDoesNotPartTheRun()
	{
		wave(1, 100, 1);
		log.finish(WaveLog.End.COMPLETED);
		wave(2, 200, 1);
		log.finish(WaveLog.End.LEFT);
		wave(3, 300, 1);
		assertEquals(Arrays.asList(1, 2, 3), runWaves());
	}

	@Test
	public void aWholeRunIsAlwaysKept()
	{
		// Three runs of all 12 waves, Sol Heredit's included: the logs kept are more than a run's waves, so that the newest
		// run is whole at each wave even once the oldest logs are dropped.
		int tick = 0;
		for (int run = 0; run < 3; run++)
		{
			for (int w = 1; w <= ColosseumTracker.LAST_WAVE + 1; w++)
			{
				tick += 100;
				wave(w, tick, 1);
				log.finish(WaveLog.End.COMPLETED);
				List<Integer> expected = new ArrayList<>();
				for (int i = 1; i <= w; i++)
				{
					expected.add(i);
				}
				assertEquals(expected, runWaves());
			}
		}
		assertEquals(WaveLog.MAX_PAST, log.getPast().size());
	}

	@Test
	public void theRunsBeforeTheNewestArePartedTheSameWay()
	{
		// A run of waves 1 to 3, then a new run from wave 1, then the plugin picking up at wave 6 after missing some.
		int tick = 100;
		for (int w : new int[]{1, 2, 3, 1, 2, 6, 7})
		{
			wave(w, tick, 1);
			log.finish(WaveLog.End.COMPLETED);
			tick += 100;
		}
		List<List<Integer>> runs = new ArrayList<>();
		for (List<WaveLog.Past> run : log.getRuns())
		{
			List<Integer> waves = new ArrayList<>();
			for (WaveLog.Past p : run)
			{
				waves.add(p.getWave());
			}
			runs.add(waves);
		}
		assertEquals(Arrays.asList(Arrays.asList(6, 7), Arrays.asList(1, 2), Arrays.asList(1, 2, 3)), runs);
		assertEquals(Arrays.asList(6, 7), runWaves());
		assertTrue(log.getRuns().get(2).get(0).getJson().contains("\"wave\":1"));
	}

	@Test
	public void eachWaveKeepsItsStartAndTheTickItsReinforcementsCame()
	{
		log.start(4, 100, Collections.emptyMap(), true, "test", START_STATE);
		log.record(100, player(7, 15, 99), Collections.emptyList());
		assertTrue(!log.hasReinforcementState());
		log.reinforcementsCame("{\"first\":true}");
		// Only the first tick they came is kept.
		log.reinforcementsCame("{\"second\":true}");
		WaveLog.Past now = log.getRun().get(0);
		assertTrue(now.isRecording());
		assertEquals(Arrays.asList(START_STATE, "{\"first\":true}"), Arrays.asList(now.getStartState(), now.getReinforcementState()));

		log.finish(WaveLog.End.COMPLETED);
		// After the wave, none are taken: the next wave's come with its own.
		log.reinforcementsCame("{\"late\":true}");
		log.start(5, 200, Collections.emptyMap(), true, "test", null);
		WaveLog.Past four = log.getPast().get(0);
		assertEquals(Arrays.asList(START_STATE, "{\"first\":true}"), Arrays.asList(four.getStartState(), four.getReinforcementState()));
		assertTrue(!four.isRecording());
		WaveLog.Past five = log.getRun().get(1);
		assertEquals(Arrays.asList(null, null), Arrays.asList(five.getStartState(), five.getReinforcementState()));
		log.finish(WaveLog.End.LEFT);
		log.reinforcementsCame("{\"after\":true}");
		assertEquals(null, log.getReinforcementState());
	}

	@Test
	public void noLogNoRun()
	{
		assertTrue(log.getRun().isEmpty());
		assertEquals("{\"v\":1,\"kind\":\"solSurvivorRun\",\"plugin\":\"test\",\"waves\":[]}", RunLogWriter.toJson(log.getRun(), "test"));

		wave(1, 100, 1);
		wave(2, 200, 1);
		log.clear();
		assertTrue(log.getRun().isEmpty());
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Random;
import java.util.zip.GZIPInputStream;
import org.junit.Test;

/**
 * The body of a run's Watch: the run's JSON gzipped, which the site stores as it comes, and a run past the site's limits
 * refused before anything is sent, with what the player can do instead.
 */
public class RunUploadTest
{
	@Test
	public void aRunIsSentGzippedAndUnpacksToItsJson() throws IOException
	{
		String json = "{\"v\":1,\"kind\":\"solSurvivorRun\",\"waves\":[" + "{\"t\":1},".repeat(10_000) + "{}]}";
		byte[] packed = RunUpload.pack(json);
		assertTrue(packed.length < json.length() / 10);
		try (GZIPInputStream in = new GZIPInputStream(new ByteArrayInputStream(packed)))
		{
			assertEquals(json, new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
		assertEquals("application/gzip", RunUpload.TYPE);
	}

	@Test
	public void aRunPastTheSitesLimitsIsRefusedWithWhatThePlayerCanDo()
	{
		String tooLong = "x".repeat(RunUpload.MAX_JSON_BYTES + 1);
		assertRefused(tooLong, "This run is too large to open (8 MiB maximum). You can still copy its wave logs.");
		// Noise does not pack: past the stored size, it is refused too.
		byte[] noise = new byte[RunUpload.MAX_PACKED_BYTES];
		new Random(7).nextBytes(noise);
		StringBuilder hex = new StringBuilder();
		for (byte b : noise)
		{
			hex.append(String.format("%02x", b));
		}
		assertRefused(hex.toString(), "This run is too large to store on the site. You can still copy its wave logs.");
	}

	private static void assertRefused(String json, String message)
	{
		try
		{
			RunUpload.pack(json);
			fail("packed a run past the site's limits");
		}
		catch (RunUpload.TooLarge ex)
		{
			assertEquals(message, ex.getMessage());
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import org.junit.Test;

/**
 * The packed link text (StatePayload.pack): it unpacks, against the site's dictionary, to the JSON it was made from, and
 * it is about half as long. The site's tests unpack the plugin's packed fixture and compare the plugin's copy of the
 * dictionary with the site's, byte for byte (test/link/pluginFixtures.test.ts).
 */
public class StatePayloadTest
{
	/** The state fixtures, each a payload as toJson writes it. */
	private static final String[] FIXTURES = {"wave4-start.json", "wave4-mid.json", "late-start.json", "wave8-gear.json"};

	static String fixture(String name) throws IOException
	{
		try (InputStream in = StatePayloadTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	/** Packed link text unpacked to its JSON, as the site's unpackStateText does it; an AssertionError if it does not unpack. */
	static String unpack(String text)
	{
		assertTrue(text.startsWith(StatePayload.PACKED_V1));
		Inflater inflater = new Inflater(true);
		try
		{
			inflater.setDictionary(StatePayload.DICTIONARY_V1);
			inflater.setInput(Base64.getUrlDecoder().decode(text.substring(StatePayload.PACKED_V1.length())));
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buffer = new byte[4096];
			while (!inflater.finished())
			{
				int n = inflater.inflate(buffer);
				if (n == 0 && inflater.needsInput())
				{
					throw new AssertionError("the packed text is cut short");
				}
				out.write(buffer, 0, n);
			}
			return out.toString(StandardCharsets.US_ASCII);
		}
		catch (DataFormatException e)
		{
			throw new AssertionError("the packed text does not unpack", e);
		}
		finally
		{
			inflater.end();
		}
	}

	@Test
	public void theSitesDictionaryIsThere()
	{
		assertNotNull(StatePayload.DICTIONARY_V1);
		assertEquals(1496, StatePayload.DICTIONARY_V1.length);
	}

	@Test
	public void aPackedPayloadUnpacksToItsJsonAtLessThanThreeFifthsOfTheLength() throws Exception
	{
		for (String name : FIXTURES)
		{
			String json = fixture(name);
			String packed = StatePayload.pack(json);
			String plain = Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.US_ASCII));
			assertEquals(name, json, unpack(packed));
			assertTrue(name + ": " + packed.length() + " against " + plain.length(), packed.length() * 5 < plain.length() * 3);
		}
	}

	@Test
	public void theTrianglesPlaceComesAfterTheRestOfTheLink() throws Exception
	{
		// wave4-triangle.json is wave4-start.json with the dot of the site's readout "Safe 10% · Fast 0% · Easy 90%", which
		// the site's tests open (test/link/pluginFixtures.test.ts).
		String start = fixture("wave4-start.json");
		TriangleDot dot = TriangleDot.of(10, 0, 90);
		assertEquals(fixture("wave4-triangle.json"), StatePayload.withTriangle(start, dot));
		String link = StatePayload.linkOfJson("https://solsurvivor.app/", start, dot);
		assertEquals(fixture("wave4-triangle.json"), unpack(link.substring(link.indexOf(StatePayload.STATE_HASH) + StatePayload.STATE_HASH.length())));
		// Without one, the link is as it was.
		assertEquals(start, StatePayload.withTriangle(start, null));
		assertEquals(StatePayload.linkOfJson("https://solsurvivor.app/", start), StatePayload.linkOfJson("https://solsurvivor.app/", start, null));
	}

	@Test
	public void theTrianglesSharesAreKeptToTheSettingsRangeAndNoneAboveNothingPlacesNoDot()
	{
		assertEquals(TriangleDot.of(0, 100, 0), TriangleDot.of(-5, 200, 0));
		assertEquals(TriangleDot.MAX_SHARE, TriangleDot.of(33, 101, 33).getFast());
		assertNull(TriangleDot.of(0, 0, 0));
		assertNull(TriangleDot.of(-1, 0, -40));
	}

	@Test
	public void thePackedFixtureIsAWaveStartsLink() throws Exception
	{
		// wave4-start.packed.txt is this plugin's packing of wave4-start.json, which the site's tests unpack too. It is not
		// compared with pack's text today: another zlib may deflate the same bytes otherwise, and both read the same.
		assertEquals(fixture("wave4-start.json"), unpack(fixture("wave4-start.packed.txt")));
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import org.junit.Before;
import org.junit.Test;

/**
 * The wave log, fed mocked game data as the RuneLite layer passes it on: a wave's start from the tracker, the hitsplats
 * as they come and a snapshot of the player and the NPCs each tick. The JSON is compared whole with
 * src/test/resources/fixtures/wave-log.json. The animation, graphic, item and hitsplat type ids here are made up: the
 * log passes on whatever the game gives.
 */
public class WaveLogTest
{
	private static final int FREM_RANGER_ID = 12814;
	/** An NPC the plugin has no kind for, logged by its raw id all the same: Minimus, here standing on the grid. */
	private static final int MINIMUS_ID = 12808;
	/** The state link's payload on the wave's first tick, as the RuneLite layer passes it on: here a short made-up one. */
	private static final String START_STATE = "{\"v\":1,\"setup\":{\"npcs\":[[13,20,\"2\"]],\"player\":[7,15],\"waveStart\":true,\"wave\":4}}";
	/** Gear worn, slot by slot in WaveLog.WORN_SLOTS' order: a bow, then a fang in its place. */
	private static final int[] BOW = {1001, 1002, -1, 1004, 1005, -1, 1007, -1, -1, -1, 1011};
	private static final int[] FANG = {1001, 1002, -1, 2004, 1005, -1, 1007, -1, -1, -1, 1011};
	/** The game's counters, one for each ColosseumCounter in its order: Doom's stacks, the glory, the times and the damage. */
	private static final int[] COUNTERS = {0, 1200, 51000, 0, 150, 120, 900};
	private static final int[] COUNTERS_HIT = {0, 1200, 51000, 13, 150, 120, 900};

	private WaveLog log;

	@Before
	public void setUp()
	{
		log = new WaveLog();
	}

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = WaveLogTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	private static WaveLog.PlayerTick player(int x, int y, int hp, int prayer, List<String> prayers, int animation, int target)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), hp, prayer, prayers, animation, target);
	}

	private static WaveLog.PlayerTick wearing(int[] worn, int x, int y)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE, worn);
	}

	private static WaveLog.NpcTick npc(int index, int id, int x, int y, int animation, int ratio, int scale, int target)
	{
		return new WaveLog.NpcTick(index, id, new GridTile(x, y), animation, ratio, scale, target);
	}

	/** Wave 4 started by the tracker, with Reentry II, Quartet and Totemic taken and Solarflare I's varbit set. */
	private void startWave4(int gameTick)
	{
		ColosseumTracker tracker = new ColosseumTracker();
		tracker.onModifierOptions(Modifier.SOLARFLARE.getId(), Modifier.QUARTET.getId(), Modifier.DOOM.getId(),
			(1 << Modifier.REENTRY.getId()) | (1 << Modifier.TOTEMIC.getId()));
		tracker.onModifierChosen(2);
		Map<Modifier, Integer> varbits = new EnumMap<>(Modifier.class);
		varbits.put(Modifier.REENTRY, 2);
		varbits.put(Modifier.SOLARFLARE, 1);
		tracker.onGameMessage("<col=ef1020>Wave: 4</col>", gameTick);
		assertTrue(tracker.isWaveStartTick(gameTick));
		log.start(tracker.getWave(), gameTick, tracker.modifiers(m -> varbits.getOrDefault(m, 0)), tracker.isModifiersComplete(), "test",
			START_STATE);
	}

	@Test
	public void aWaveLog() throws Exception
	{
		// A hitsplat that came on the wave's first tick, before the tracker saw its message, is kept for that tick.
		log.onNpcHit(12, 0, 12);
		startWave4(100);
		log.record(100, new WaveLog.PlayerTick(new GridTile(7, 15), 99, 77, Arrays.asList("magic", "piety"), -1, WaveLog.TARGET_NONE, BOW),
			Arrays.asList(
			npc(11, NpcKind.SHAMAN_ID, 13, 20, -1, -1, -1, WaveLog.TARGET_PLAYER),
			npc(12, NpcKind.MANTICORE_ID, 16, 24, 7590, 30, 30, WaveLog.TARGET_PLAYER),
			npc(13, FREM_RANGER_ID, 7, 14, -1, -1, -1, WaveLog.TARGET_NONE),
			npc(20, NpcKind.SOLARFLARE_ORB_ID, 4, 4, -1, -1, -1, WaveLog.TARGET_NONE),
			// Off the grid: left out.
			npc(21, MINIMUS_ID, 40, 4, -1, -1, -1, WaveLog.TARGET_NONE)), COUNTERS);

		log.onPlayerHit(13, 16);
		log.onPlayerHit(0, 17);
		log.onNpcHit(11, 21, 12);
		log.onNpcHit(11, 9, 12);
		// The player switched to the fang and struck twice with the same animation; the Manticore showed an orb.
		log.onPlayerAnimation(7552);
		log.onPlayerAnimation(7552);
		// A graphic on a tile of the grid is kept, one off it is not.
		log.onTileGraphic(new GridTile(9, 12), 4001);
		log.onTileGraphic(new GridTile(40, 4), 4002);
		// The Manticore's orb at the player; a special aimed at a tile, seen a tick late; and one with nothing on the grid at
		// either end, which is left out. The damage taken counts up, and only it is listed.
		log.onProjectile(new WaveLog.Projectile(5001, 12, null, WaveLog.TARGET_PLAYER, null, 0, 51));
		log.onProjectile(new WaveLog.Projectile(5002, 11, new GridTile(1, 1), WaveLog.TARGET_NONE, new GridTile(9, 12), -12, 48));
		log.onProjectile(new WaveLog.Projectile(5003, WaveLog.TARGET_NONE, new GridTile(40, 4), WaveLog.TARGET_NONE, null, 0, 30));
		log.record(101, new WaveLog.PlayerTick(new GridTile(7, 14), 86, 75, Arrays.asList("ranged", "rigour"), 7552, 11, FANG), Arrays.asList(
			npc(11, NpcKind.SHAMAN_ID, 13, 19, 7579, 20, 30, WaveLog.TARGET_PLAYER),
			new WaveLog.NpcTick(12, NpcKind.MANTICORE_ID, new GridTile(16, 23), -1, 30, 30, WaveLog.TARGET_PLAYER, new int[] {3001}),
