		{
			log.start(7, 400 + i, Collections.emptyMap(), true, "test", null);
		}
		assertEquals(WaveLog.MAX_PAST, log.getPast().size());

		log.clear();
		assertTrue(log.getPast().isEmpty());
		assertEquals(0, log.getId());
	}

