/**
 * The wave logs the player shares with "Share wave logs": a random id for each run and none that outlives it, each log
 * once, gzipped, and its gear without the levels or the prayer unlocks, which the site refuses in a shared log.
 */
public class WaveShareTest
{
	private static final String START = "{\"v\":1,\"setup\":{\"wave\":4},\"equipment\":{\"stats\":{\"ranged\":[112,99]}}}";
	private static final String SHARED_START = "{\"v\":1,\"setup\":{\"wave\":4},\"equipment\":{\"stats\":{}}}";

	@Test
	public void aRunKeepsItsIdWaveAfterWaveAndANewRunGetsANewOne()
	{
		WaveShare share = new WaveShare(new Random(7));
		assertNull(share.getRun());
		String run = share.onWaveStart(1);
		assertTrue(run, run.matches("[a-f0-9]{32}"));
		assertEquals(run, share.onWaveStart(2));
		assertEquals(run, share.getRun());
		// A wave that does not follow the last one is another run, as is wave 1 again.
		String next = share.onWaveStart(5);
		assertNotEquals(run, next);
		assertNotEquals(next, share.onWaveStart(1));
	}

	@Test
	public void leavingTheArenaForgetsTheRun()
	{
		WaveShare share = new WaveShare(new Random(7));
		String run = share.onWaveStart(3);
		share.onLeave();
		assertNull(share.getRun());
		// A plugin started mid-run, or back after leaving, starts a run of its own at the next wave.
		String next = share.onWaveStart(4);
		assertTrue(next.matches("[a-f0-9]{32}"));
		assertNotEquals(run, next);
	}

	@Test
	public void eachLogIsClaimedOnceAndNoLogNever()
	{
		WaveShare share = new WaveShare(new Random(7));
		assertFalse(share.claim(0));
		assertTrue(share.claim(1));
		assertFalse(share.claim(1));
		assertTrue(share.claim(2));
	}

	@Test
	public void theBodyIsTheLogGzipped() throws IOException
	{
		String json = "{\"v\":1,\"kind\":\"solSurvivorWaveLog\",\"ticks\":[]}";
		byte[] body = WaveShare.gzip(json);
		try (GZIPInputStream in = new GZIPInputStream(new ByteArrayInputStream(body)))
		{
			assertEquals(json, new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
	}

	@Test
	public void itPostsToTheSitesOwnEndpoint()
	{
		assertEquals("https://solsurvivor.app/api/wave-logs", WaveShare.endpoint("https://solsurvivor.app/"));
	}

	@Test
	public void theSharedLogStartsWithTheGearWithoutTheLevels()
	{
		WaveLog log = new WaveLog();
		log.start(4, 100, new EnumMap<>(Modifier.class), true, "0.7.0", START, SHARED_START);
		log.record(100, new WaveLog.PlayerTick(new GridTile(7, 15), 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE),
			Collections.emptyList());
		String copied = WaveLogWriter.toJson(log);
		String shared = WaveLogWriter.toShare(log);
		assertTrue(copied, copied.contains("\"start\":" + START));
		assertTrue(shared, shared.contains("\"start\":" + SHARED_START));
		// Everything else is the log as Copy wave log copies it.
		assertEquals(copied.replace(START, SHARED_START), shared);
		// A start given once is shared as it is.
		log.start(5, 200, new EnumMap<>(Modifier.class), true, "0.7.0", SHARED_START);
		assertTrue(WaveLogWriter.toShare(log).contains("\"start\":" + SHARED_START));
	}

	@Test
	public void gearWithoutLevelsKeepsEverythingButTheLevelsAndTheUnlocks()
	{
		Equipment gear = new Equipment()
			.item("weapon", new Equipment.Item(20997, "Twisted bow", 1))
			.switchItem("weapon", new Equipment.Item(22325, "Scythe of vitur", 1), 5)
			.bonuses(20997, new int[]{0, 0, 0, 0, 70, 0, 20, 0, 1})
			.defences(20997, new int[]{0, 0, 0, 0, 0})
			.weapon(5, 3, 1)
			.prayer(9, 77)
			.stat("ranged", 112, 99)
			.unlocks(1, 0, 1, 0, 8, 0);
		Equipment shared = gear.withoutLevels();
		assertTrue(shared.getStats().isEmpty());
		assertNull(shared.getUnlocks());
		assertEquals(gear.getItems().keySet(), shared.getItems().keySet());
		assertEquals(1, shared.getSwitches().size());
		assertArrayEquals(gear.getBonuses().get(20997), shared.getBonuses().get(20997));
		assertArrayEquals(gear.getDefences().get(20997), shared.getDefences().get(20997));
		assertEquals(5, shared.getWeaponSpeed());
		assertEquals(9, shared.getPrayerBonus());
		assertEquals(77, shared.getPrayerPoints());
		// The gear it was made from keeps its levels.
		assertEquals(1, gear.getStats().size());
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * A wave saved by "Keep runs between sessions" and read back, as the RuneLite layer writes and reads its files, and the
 * names it gives them, which sort as the waves were saved.
 */
public class WaveStoreTest
{
	private static final String START_STATE = "{\"v\":1,\"setup\":{\"npcs\":[[13,20,\"2\"]],\"player\":[7,15],\"waveStart\":true,\"wave\":4}}";

	private static byte[] saved(WaveLog.Past wave) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		WaveStore.write(wave, out);
		return out.toByteArray();
	}

	@Test
	public void aWaveComesBackAsItWasSaved() throws IOException
	{
		// Wave 4 as the plugin saves it as it ends: its log, written as it is saved, and its state on the first tick and
		// when the reinforcements came, the glory it earned, and a name in the log that is not ASCII.
		WaveLog log = new WaveLog();
		log.start(4, 100, Collections.emptyMap(), true, "test", START_STATE);
		log.record(100, new WaveLog.PlayerTick(new GridTile(7, 15), 99, 77, Arrays.asList("magic"), -1, WaveLog.TARGET_NONE),
			Collections.emptyList(), new int[] {0, 1200, 51000, 0, 150, 120, 900});
		log.reinforcementsCame("{\"v\":1,\"setup\":{\"wave\":4,\"note\":\"Fortis été\"}}");
		log.record(101, new WaveLog.PlayerTick(new GridTile(7, 14), 99, 77, Arrays.asList("magic"), -1, WaveLog.TARGET_NONE),
			Collections.emptyList(), new int[] {0, 2180, 51000, 0, 150, 120, 900});
		log.finish(WaveLog.End.COMPLETED);
		WaveLog.Past wave = log.current();

		WaveLog.Past back = WaveStore.read(new ByteArrayInputStream(saved(wave)));
		assertEquals(0, back.getId());
		assertEquals(4, back.getWave());
		assertEquals(2, back.size());
		assertEquals(WaveLog.End.COMPLETED, back.getEnd());
		assertFalse(back.isRecording());
		assertEquals(Integer.valueOf(980), back.getGlory());
		assertEquals(START_STATE, back.getStartState());
		assertEquals(wave.getReinforcementState(), back.getReinforcementState());
		assertEquals(WaveLogWriter.toJson(log), back.getJson());
	}

	@Test
	public void aWaveWithoutItsStatesEndOrGloryComesBackWithoutThem() throws IOException
	{
		WaveLog.Past wave = new WaveLog.Past(7, 2, 140, null, false, () -> "{}", null, null, null);
		WaveLog.Past back = WaveStore.read(new ByteArrayInputStream(saved(wave)));
		assertNull(back.getEnd());
		assertNull(back.getGlory());
		assertNull(back.getStartState());
		assertNull(back.getReinforcementState());
		assertEquals("{}", back.getJson());

		WaveLog.Past left = new WaveLog.Past(7, 3, 90, WaveLog.End.LEFT, false, () -> "{}", null, null, null);
		assertEquals(WaveLog.End.LEFT, WaveStore.read(new ByteArrayInputStream(saved(left))).getEnd());
	}

	@Test
	public void aFileThatIsNotASavedWaveOrIsCutShortIsNotRead() throws IOException
	{
		byte[] bytes = saved(new WaveLog.Past(7, 2, 140, WaveLog.End.COMPLETED, false, () -> "{\"wave\":2}", START_STATE, null, 1114));
		for (byte[] bad : Arrays.asList(Arrays.copyOf(bytes, bytes.length / 2), "not a wave".getBytes(), WaveShare.gzip("{\"v\":1}")))
		{
			try
			{
				WaveStore.read(new ByteArrayInputStream(bad));
				fail("read a file that is not a whole saved wave");
			}
			catch (IOException expected)
			{
				// As the RuneLite layer passes such a file over.
			}
		}
	}

	@Test
	public void theNamesSortAsTheWavesWereSavedAndThoseBeyondTheNewestAreToGo()
	{
		String first = WaveStore.fileName(1_761_480_000_000L, 1);
		String second = WaveStore.fileName(1_761_480_090_000L, 2);
		String third = WaveStore.fileName(1_761_480_250_000L, 10);
		assertEquals("1761480000000-wave01.wave.gz", first);
		assertTrue(third.endsWith("-wave10.wave.gz"));
		List<String> names = new ArrayList<>(Arrays.asList(second, "notes.txt", third, first));
		assertEquals(Arrays.asList(third, second, first), WaveStore.newestFirst(names));
		assertEquals(Collections.singletonList(first), WaveStore.beyond(names, 2));
		assertTrue(WaveStore.beyond(names, 3).isEmpty());
		assertEquals(WaveLog.MAX_PAST + 1, WaveStore.MAX_SAVED);
	}
}
